-- FlareUI 문구, 영어(기본 언어). 게임에서 불러오지 않음: 모든 키는 각각의
-- 영어 텍스트임(Locale/Locale.lua는 키를 기본값으로 사용함). 이 목록은 CurseForge의
-- 현지화 도구에서 가져오는 항목이며, 번역 결과는 패키징 도구를 통해 다른 파일에 반영됨.
-- 코드에 있는 모든 L["..."] 항목에서 생성됨(tools/enus.js). 직접 수정하지 말 것.
local L = {}
L["..."] = "..."
L["(Complete)"] = "(완료)"
L["(current zone)"] = "(현재 지역)"
L["(first %d shown)"] = "(처음 %d개 표시)"
L["(map ID)"] = "(지도 ID)"
L["(named zone)"] = "(이름이 지정된 지역)"
L["(Shown while another bag addon is loaded; the panel writes the addon's name into its own line.)"] = "(다른 가방 애드온이 로드되어 있을 때 표시됩니다. 패널은 해당 애드온의 이름을 별도 줄에 표시합니다.)"
L["(you)"] = "(나)"
L["{Module} is off. Its settings appear here once it's on."] = "{Module}이(가) 꺼져 있습니다. 켜면 여기에 설정이 표시됩니다."
L["{n} change(s) need a reload"] = "{n}개의 변경 사항을 적용하려면 다시 불러와야 합니다."
L["* A cleaner chat with FlareUI's header and tabs\n* Class colours, short channel names and link icons\n* A copy button, and fading when quiet"] = "* FlareUI 머리글과 탭으로 더 깔끔해진 채팅\n* 직업 색상, 짧은 채널 이름 및 링크 아이콘\n* 복사 버튼과 채팅이 조용할 때 서서히 사라지는 기능"
L["* A ring of spells, items, macros and more\n* Hold the key, point, release\n* Works with a gamepad too"] = "* 주문, 아이템, 매크로 등을 담는 원형 메뉴\n* 키를 누른 채 원하는 항목을 가리킨 다음 놓으세요.\n* 게임패드도 지원합니다."
L["* A square or round minimap\n* Coordinates, framerate and latency\n* A drawer for addon buttons"] = "* 사각형 또는 원형 미니맵\n* 좌표, 프레임률 및 지연 시간\n* 애드온 버튼을 모아 두는 서랍"
L["* An icon for each buff you or your group are missing\n* Food, flasks, elixirs, weapon oils and low supplies\n* Click an icon to cast or use it"] = "* 자신이나 파티원에게 없는 강화 효과를 아이콘으로 표시\n* 음식, 영약, 비약, 무기 기름 및 부족한 보급품 표시\n* 아이콘을 클릭해 주문을 시전하거나 아이템 사용"
L["* Auto quests, auto repair and junk selling\n* Camera and vendor helpers\n* Hides clutter like error and zone text"] = "* 자동 퀘스트, 자동 수리 및 잡동사니 판매\n* 카메라 및 상인 관련 편의 기능\n* 오류 메시지와 지역 텍스트 같은 불필요한 요소 숨기기"
L["* Blizzard's damage meter in a FlareUI frame\n* A threat view for tanks and damage dealers\n* Extra meter windows that dock as tabs"] = "* FlareUI 프레임 안에 표시되는 블리자드 피해량 측정기\n* 방어 담당자와 공격 담당자를 위한 위협 수준 보기\n* 탭으로 고정할 수 있는 추가 측정기 창"
L["* Cleaner tooltips with coloured borders\n* A health bar, target and threat lines if you want them\n* Tooltips that can follow your mouse"] = "* 색상 테두리로 더 깔끔해진 툴팁\n* 원하는 경우 생명력 바, 대상 및 위협 수준 표시\n* 마우스를 따라다니는 툴팁"
L["* Doggie art by |cffffd100Clari Turela|r.\n* |cffffd100sampconrad|r for the help with aura frames.\n* |cffffd100Jeor|r for the settings' new look idea.\n* |cffffd100parchinskiy|r for too many things to list here.\n* |cffffd100Kabaday|r for the loot roll window and the Cooldown Manager.\n* |cffffd100Celbrund|r for the minimap Info Bar.\n* |cffffd100Bill|r for improving the addon's testing."] = "* 강아지 그림: |cffffd100Clari Turela|r.\n* 오라 프레임 지원: |cffffd100sampconrad|r.\n* 설정 화면의 새로운 디자인 아이디어: |cffffd100Jeor|r.\n* 여기에 모두 나열하기 어려울 만큼 많은 도움을 준 |cffffd100parchinskiy|r.\n* 전리품 주사위 굴림 창과 재사용 대기시간 관리자: |cffffd100Kabaday|r.\n* 미니맵 정보 바: |cffffd100Celbrund|r.\n* 애드온 테스트 개선: |cffffd100Bill|r."
L["* Drag buttons in the drawer to reorder them\n* Changes apply after a reload\n* New addons go in the drawer\n* While OneForAll's \"Collect minimap buttons\" is on, its bar takes the minimap buttons: only the Addon Compartment entries are listed here"] = "* 서랍의 버튼을 드래그해 순서를 변경하세요.\n* 변경 사항은 다시 불러온 후 적용됩니다.\n* 새 애드온은 서랍에 추가됩니다.\n* OneForAll의 \"미니맵 버튼 모으기\"가 켜져 있으면 해당 애드온의 바가 미니맵 버튼을 가져갑니다. 이 경우 여기에 애드온 보관함 항목만 표시됩니다."
L["* Export: the profile in use as a text string to share\n* Import: paste a string and pick the parts to take, as a new profile or into the one in use"] = "* 내보내기: 현재 사용 중인 프로필을 공유할 수 있는 텍스트 문자열로 내보냅니다.\n* 가져오기: 문자열을 붙여넣고 가져올 항목을 선택합니다. 새 프로필로 만들거나 현재 프로필에 적용할 수 있습니다."
L["* FlareUI's bag and bank windows\n* Category filters and item levels\n* A loot roll window and a loot feed"] = "* FlareUI의 가방 및 은행 창\n* 범주 필터 및 아이템 레벨\n* 전리품 주사위 굴림 창 및 전리품 알림"
L["* FlareUI's borders, proc glows and status colours on your buttons\n* An XP bar, and hide the bars you don't use\n* Fake CM: spare bars as a cooldown tracker"] = "* 버튼에 FlareUI 테두리, 발동 효과 및 상태 색상 적용\n* 경험치 바와 사용하지 않는 행동 단축바 숨기기\n* Fake CM: 여분의 바를 재사용 대기시간 추적기로 사용"
L["* FlareUI's look on the cooldown icons and bars\n* Keybinds and key presses on the icons\n* Growth, icon shape and fading in Edit Mode"] = "* 재사용 대기시간 아이콘과 바에 FlareUI 스타일 적용\n* 아이콘에 단축키 및 키 입력 표시\n* 편집 모드에서 확장 방향, 아이콘 모양 및 페이드 설정"
L["* FlareUI's own quest tracker\n* Zone headings, quest levels and quest icons\n* Minimizes itself in instances or fights"] = "* FlareUI 전용 퀘스트 추적기\n* 지역 제목, 퀘스트 레벨 및 퀘스트 아이콘\n* 던전이나 전투 중에는 자동으로 최소화"
L["* Health, power, combo points and swing timers as bars you place anywhere\n* Paladin seals, flight timers and breath timers\n* Each bar set up in Edit Mode"] = "* 생명력, 자원, 연계 점수 및 무기 공격 주기를 원하는 위치에 바 형태로 표시\n* 성기사의 문장, 비행 시간 및 호흡 시간\n* 편집 모드에서 각 바 설정"
L["* In it: every FlareUI setting, and where FlareUI's frames sit on any Edit Mode layout\n* Not in it: Blizzard's bars and frames, which come with your Edit Mode layout\n* Switching profiles offers the layout the profile was set up on.\n* From another character, copy the layout with Copy Layout Code (About) or Sync Blizzard UI (General)."] = "* 포함 항목: 모든 FlareUI 설정과 편집 모드 레이아웃에서 FlareUI 프레임이 배치된 위치\n* 제외 항목: 편집 모드 레이아웃에 포함되는 블리자드의 바와 프레임\n* 프로필을 전환하면 해당 프로필이 설정된 레이아웃을 사용할 수 있습니다.\n* 다른 캐릭터에서 레이아웃을 복사하려면 레이아웃 코드 복사(정보) 또는 블리자드 UI 동기화(일반)를 사용하세요."
L["* Nameplates for enemies and friends in the FlareUI style\n* Threat colours for tanks, damage and healers\n* Cast bars, your debuffs and crowd control on each plate\n* Every colour yours to pick"] = "* 적과 아군의 이름표에 FlareUI 스타일 적용\n* 방어 담당자, 공격 담당자 및 치유 담당자를 위한 위협 수준 색상\n* 각 이름표에 시전 바, 자신의 약화 효과 및 군중 제어 효과 표시\n* 모든 색상을 직접 선택 가능"
L["* New: a copy of the profile in use, or FlareUI's defaults\n* Rename: a new name for the profile in use\n* Delete: removes a profile you aren't using"] = "* 새로 만들기: 현재 사용 중인 프로필의 복사본 또는 FlareUI 기본 설정으로 새 프로필을 만듭니다.\n* 이름 변경: 현재 사용 중인 프로필의 이름을 변경합니다.\n* 삭제: 사용하지 않는 프로필을 제거합니다."
L["* Pick the Unit to change: enemy or friendly players, enemy or friendly NPCs, or Minor (minor mobs, pets, totems and guardians).\n* Pick a Preset. Change any setting and it becomes Custom, saved for that unit.\n* Live Preview shows everything the plate can show. Test in Game puts it on the plates around you."] = "* 변경할 유닛을 선택하세요: 적대적 또는 우호적 플레이어, 적대적 또는 우호적 NPC, 또는 하급 유닛(하급 몬스터, 소환수, 토템 및 수호자).\n* 사전 설정을 선택하세요. 설정을 하나라도 변경하면 사용자 설정으로 바뀌며 해당 유닛에 저장됩니다.\n* 실시간 미리 보기에서는 이름표에 표시할 수 있는 모든 항목을 확인할 수 있습니다. 게임 내 테스트를 누르면 주변 이름표에 적용됩니다."
L["* Player, target, focus, pet, party, raid and boss frames\n* Three styles: FlareUI, Forever and Modern\n* Size, text, auras and fading for each frame in Edit Mode"] = "* 플레이어, 대상, 주시 대상, 소환수, 파티, 공격대 및 우두머리 프레임\n* 세 가지 스타일: FlareUI, Forever 및 Modern\n* 편집 모드에서 각 프레임의 크기, 텍스트, 오라 및 페이드 설정"
L["* Spare action bars as a cooldown tracker: your spells, your order, any count per row.\n* Ticked bars can't be clicked and show only when Visibility says.\n* A button flashes when its cooldown ends.\n* Drag a spell onto them to change it, or use Fake CM Setup Mode (`/fui cm`).\n* Edit Mode always shows them: move and size them as any action bar."] = "* 여분의 행동 단축바를 재사용 대기시간 추적기로 사용합니다. 주문과 순서를 직접 정하고, 한 줄에 원하는 개수만큼 배치할 수 있습니다.\n* 선택된 바는 클릭할 수 없으며 표시 설정에 따라 나타납니다.\n* 재사용 대기시간이 끝나면 버튼이 깜박입니다.\n* 주문을 바 위로 드래그해 변경하거나 Fake CM 설정 모드(`/fui cm`)를 사용하세요.\n* 편집 모드에서는 항상 표시됩니다. 다른 행동 단축바처럼 위치와 크기를 조정할 수 있습니다."
L["* Use Global Font Everywhere: sets every FlareUI font to Global. Sizes, outlines and shadows stay as they are.\n* Reset All Fonts: every FlareUI font, and the Global Font, back to defaults."] = "* 전역 글꼴 모두 사용: 모든 FlareUI 글꼴을 전역 글꼴로 설정합니다. 크기, 윤곽선 및 그림자 설정은 유지됩니다.\n* 모든 글꼴 초기화: 모든 FlareUI 글꼴과 전역 글꼴을 기본값으로 되돌립니다."
L["* Your buffs and debuffs in FlareUI's look\n* Round or square icons, timers and sorting\n* Hide any aura, or always show it, on any frame\n* Size and placement in Edit Mode"] = "* 자신의 강화 효과와 약화 효과를 FlareUI 스타일로 표시\n* 원형 또는 사각형 아이콘, 지속 시간 및 정렬\n* 모든 프레임에서 원하는 오라를 숨기거나 항상 표시\n* 편집 모드에서 크기 및 위치 설정"
L["/fui pad still switches. It never asks while ConsolePort or another controller addon is loaded."] = "/fui pad 명령으로도 전환할 수 있습니다. ConsolePort 또는 다른 컨트롤러 애드온이 로드되어 있는 동안에는 확인 메시지를 표시하지 않습니다."
L["/way is off in the Quality of Life settings."] = "편의 기능 설정에서 /way가 꺼져 있습니다."
L["/way usage:"] = "/way 사용법:"
L["%d found for \"%s\""] = "\"%s\"에서 %d개를 찾았습니다."
L["%s (copy)"] = "%s (복사본)"
L["%s (R%d)"] = "%s (등급 %d)"
L["%s by |cffb39ddbMalkkav|r. Type |cffffff00/fui|r for settings."] = "%s 제작: |cffb39ddbMalkkav|r. 설정을 열려면 |cffffff00/fui|r를 입력하세요."
L["%s finds gathering nodes by sliding the minimap under your cursor. While it scans, the map and what is on it (quest areas, icons) can flash or vanish for a moment.\n\nThat comes from the addon itself, not FlareUI, and happens on Blizzard's minimap too. NodeRadar, FarmMap and GatherMemory find nodes without moving the map."] = "%s은(는) 커서 아래에서 미니맵을 움직이며 채집 지점을 찾습니다. 탐색하는 동안 지도와 지도에 표시된 요소(퀘스트 지역, 아이콘)가 잠시 깜박이거나 사라질 수 있습니다.\n\n이는 FlareUI가 아니라 해당 애드온 자체의 동작이며, 블리자드 기본 미니맵에서도 발생합니다. NodeRadar, FarmMap 및 GatherMemory는 지도를 움직이지 않고 채집 지점을 찾습니다."
L["%s for bandages."] = "붕대용 %s."
L["%s holds %s. Put the radial there instead?"] = "%s에 %s이(가) 지정되어 있습니다. 대신 원형 메뉴를 여기에 배치할까요?"
L["%s incoming!"] = "%s 접근 중!"
L["%s is bound to %s. Use it anyway?"] = "%s이(가) %s에 지정되어 있습니다. 그래도 사용하시겠습니까?"
L["%s is bound to %s. Use it for this radial anyway?"] = "%s이(가) %s에 지정되어 있습니다. 그래도 이 원형 메뉴에 사용하시겠습니까?"
L["%s is handling your bags: turn it off to use these options."] = "%s이(가) 가방을 관리하고 있습니다. 이 옵션을 사용하려면 해당 애드온을 끄세요."
L["%s is handling your chat, so FlareUI's chat stays off. Turn %s off to use FlareUI's."] = "%s이(가) 채팅을 관리하고 있으므로 FlareUI 채팅은 꺼져 있습니다. FlareUI 채팅을 사용하려면 %s을(를) 끄세요."
L["%s is kept for Target Mouseover"] = "%s은(는) 마우스오버 대상 지정에 사용하도록 예약되어 있습니다."
L["%s is kept for Target Mouseover. Pick a key without it."] = "%s은(는) 마우스오버 대상 지정에 사용하도록 예약되어 있습니다. 해당 키를 제외한 다른 키를 선택하세요."
L["%s moves the minimap into its farming HUD while the HUD is on. The map is then the addon's: FlareUI puts its own minimap back when you turn the HUD off.\n\nIf the minimap still looks wrong after that, type /reload."] = "%s은(는) 채집 HUD가 켜져 있는 동안 미니맵을 해당 HUD 안으로 이동합니다. 이때 미니맵은 해당 애드온이 관리합니다. HUD를 끄면 FlareUI가 자체 미니맵을 다시 배치합니다.\n\n그 후에도 미니맵이 잘못 표시된다면 /reload를 입력하세요."
L["%s opens %s on this character."] = "이 캐릭터에서 %s을(를) 누르면 %s이(가) 열립니다."
L["%s to go"] = "%s 남음"
L["%s World Marker"] = "%s 세계 징표"
L["%s XP"] = "%s 경험치"
L["%s, kept"] = "%s, 예약됨"
L["`/cdm` opens it too."] = "`/cdm`을 입력해도 열 수 있습니다."
L["`/fui cm` does the same. A reload ends it."] = "`/fui cm`을 입력해도 같은 기능을 사용할 수 있습니다. 다시 불러오면 종료됩니다."
L["`/fui` open settings.\n`/fui cm` Fake CM setup mode.\n`/fui pad` switch gamepad mode on/off.\n`/fui tour` the setup tour.\n`/kb` (or `/fui kb`) Quick Keybind Mode: point at a button and press a key to bind it."] = "`/fui` 설정 열기.\n`/fui cm` Fake CM 설정 모드.\n`/fui pad` 게임패드 모드 켜기/끄기.\n`/fui tour` 설정 안내 시작.\n`/kb`(또는 `/fui kb`) 빠른 단축키 지정 모드: 버튼을 가리킨 다음 키를 눌러 단축키를 지정합니다."
L["+ New Radial"] = "+ 새 원형 메뉴"
L["+%d more"] = "+ %d개 더"
L["+%s quest XP"] = "+%s 퀘스트 경험치"
L["|cff1eff00Sample Item|r"] = "|cff1eff00예시 아이템|r"
L["|cffffd100Hide|r: the aura never shows on the ticked frames.\n|cffffd100Show|r: it always shows there, even when Only My Buffs, Only My Debuffs or Hide Buffs would leave it out. It comes after the frame's other buffs or debuffs."] = "|cffffd100숨기기|r: 선택한 프레임에 해당 오라를 표시하지 않습니다.\n|cffffd100표시|r: 내 강화 효과만 표시, 내 약화 효과만 표시 또는 강화 효과 숨기기 설정으로 표시 대상에서 제외되더라도 해당 프레임에 항상 표시합니다. 프레임의 다른 강화 효과 또는 약화 효과 뒤에 표시됩니다."
L["0 removes the power bar."] = "0으로 설정하면 자원 바가 제거됩니다."
L["0/1 Agreed spelling of 'Mrglglgl'"] = "0/1 'Mrglglgl'의 올바른 철자에 동의함"
L["0/1 Excuses accepted by Garrosh"] = "0/1 가로쉬가 변명을 받아들임"
L["0/1 Glow described as 'cosy'"] = "0/1 빛 효과를 '아늑하다'고 표현함"
L["0/1 Left boot found in the Deadmines"] = "0/1 죽음의 폐광에서 왼쪽 장화 발견"
L["0/1 Plan with 32.33% odds rehearsed"] = "0/1 성공 확률 32.33%인 계획을 예행연습함"
L["0/1 Receipt for 'Emergency Gnoll Snacks'"] = "0/1 '비상용 놀 간식' 영수증"
L["1"] = "1"
L["1/1 Name shouted"] = "1/1 이름을 외침"
L["1/1 Wife found (she was in Goldshire)"] = "1/1 아내 발견 (골드샤이어에 있었음)"
