L["10 Seconds"] = "10초"
L["100%"] = "100%"
L["1080p"] = "1080p"
L["1080p at 125%"] = "1080p, 125%"
L["110%"] = "110%"
L["110% of the tank's threat in melee, 130% at range. Not shown while you are the tank."] = "근접 공격 시 방어 담당자의 위협 수준 110%, 원거리 공격 시 130%입니다. 자신이 방어 담당자일 때는 표시되지 않습니다."
L["120%"] = "120%"
L["130%"] = "130%"
L["140%"] = "140%"
L["1440p"] = "1440p"
L["1440p at 125%"] = "1440p, 125%"
L["150%"] = "150%"
L["2"] = "2"
L["2/5 Questionable deductions explained"] = "2/5 의심스러운 추론을 설명함"
L["20"] = "20"
L["20%"] = "20%"
L["25 Players"] = "25인"
L["25%"] = "25%"
L["2D"] = "2D"
L["3"] = "3"
L["3/8 Leper gnomes reassured"] = "3/8 나병 걸린 노움들을 안심시킴"
L["30 Seconds"] = "30초"
L["30%"] = "30%"
L["35%"] = "35%"
L["4"] = "4"
L["4/8 Murlocs saying 'Hello' clearly"] = "4/8 멀록들이 '안녕하세요'라고 또렷하게 말함"
L["40 Players"] = "40인"
L["4K"] = "4K"
L["5"] = "5"
L["5 Seconds"] = "5초"
L["50%"] = "50%"
L["6/10 Kobold candles confiscated"] = "6/10 코볼트 양초 압수"
L["60%"] = "60%"
L["70%"] = "70%"
L["80%"] = "80%"
L["90%"] = "90%"
L["A bar while you're on a flight path: where you're going and the time left."] = "비행 경로를 이용하는 동안 목적지와 남은 시간을 표시하는 바입니다."
L["A big icon right of the plate while the unit is stunned, feared, polymorphed or otherwise controlled."] = "유닛이 기절, 공포, 변이 또는 그 밖의 군중 제어 효과에 걸려 있을 때 이름표 오른쪽에 큰 아이콘을 표시합니다."
L["A bright edge at the front of the cast, as on Blizzard's cast bars."] = "블리자드 기본 시전 바처럼 시전 진행 부분의 앞쪽에 밝은 테두리를 표시합니다."
L["A bright line and a soft glow at the front of the health bar. It flashes when health changes."] = "생명력 바의 앞쪽에 밝은 선과 은은한 빛을 표시합니다. 생명력이 변하면 깜박입니다."
L["A button beside Send Mail's \"To:\" lists:\n* The last character you mailed\n* Your other characters here"] = "우편 보내기의 \"받는 사람:\" 옆에 있는 버튼을 누르면 다음 목록이 표시됩니다.\n* 마지막으로 우편을 보낸 캐릭터\n* 이 서버의 다른 캐릭터"
L["A button for you and each party member: aim at a person to cast on them."] = "자신과 각 파티원을 위한 버튼입니다. 대상을 가리키면 해당 대상에게 주문을 시전합니다."
L["A cast bar under each member."] = "각 구성원 아래에 시전 바를 표시합니다."
L["A cast bar under the health bar while the unit casts. A cast you can't interrupt turns grey with a shield."] = "유닛이 주문을 시전하는 동안 생명력 바 아래에 시전 바를 표시합니다. 차단할 수 없는 시전은 방패가 표시된 회색 바가 됩니다."
L["A character shows up once you've logged in on it."] = "해당 캐릭터로 로그인하면 목록에 표시됩니다."
L["A clash means two radials share a key. The first in the list wins."] = "충돌은 두 원형 메뉴가 같은 키를 사용하는 경우를 뜻합니다. 목록에서 먼저 나오는 메뉴가 우선 적용됩니다."
L["A cleaner chat frame with a customisable header."] = "머리글을 사용자 지정할 수 있는 더 깔끔한 채팅 창입니다."
L["A click drinks one from your bags. Any rank of an elixir counts."] = "클릭하면 가방에 있는 비약을 하나 마십니다. 비약의 등급은 상관없습니다."
L["A dark outline around the letters. Sharp Outline draws cleaner edges at any size."] = "글자 주위에 어두운 윤곽선을 표시합니다. 선명한 윤곽선은 어떤 크기에서도 더 깔끔한 가장자리를 표현합니다."
L["A dispellable debuff makes the frame's border pulse in its type's colour. In the ring styles the portrait's ring pulses too."] = "해제할 수 있는 약화 효과가 있으면 해당 효과 유형의 색상으로 프레임 테두리가 맥동합니다. 원형 스타일에서는 초상화 테두리도 함께 맥동합니다."
L["A dispellable debuff on a friendly unit makes the frame's border pulse in its type's colour."] = "우호적인 유닛에게 해제할 수 있는 약화 효과가 있으면 해당 효과 유형의 색상으로 프레임 테두리가 맥동합니다."
L["A dispellable debuff on you makes the frame's border pulse in its type's colour. In the ring styles the portrait's ring pulses too."] = "자신에게 해제할 수 있는 약화 효과가 있으면 해당 효과 유형의 색상으로 프레임 테두리가 맥동합니다. 원형 스타일에서는 초상화 테두리도 함께 맥동합니다."
L["A drop shadow under the letters.\n* Soft: 1 pixel away\n* Strong: 2 pixels away"] = "글자 아래에 그림자를 표시합니다.\n* 약하게: 1픽셀 간격\n* 강하게: 2픽셀 간격"
L["A FlareUI button in the game menu (Esc), right under Shop. It opens FlareUI's settings."] = "게임 메뉴(Esc)의 상점 바로 아래에 FlareUI 버튼을 추가합니다. 이 버튼을 누르면 FlareUI 설정이 열립니다."
L["A gold dragon on elites, a silver one on rares, on the plate's top right corner."] = "정예 몬스터에는 금색 용, 희귀 몬스터에는 은색 용을 이름표 오른쪽 위 모서리에 표시합니다."
L["A gold edge and a light on the active button:\n* Your stance or form\n* A queued Heroic Strike, Cleave, Maul or Raptor Strike (it pulses)\n* Auto Shot and wands while they repeat"] = "활성화된 버튼에 금색 테두리와 빛을 표시합니다.\n* 자신의 태세 또는 변신 형태\n* 예약된 영웅의 일격, 회전베기, 후려치기 또는 랩터의 일격(맥동 효과)\n* 자동 사격 및 반복해서 발사되는 마법봉"
L["A green \">\" before whispers you get and a red \"<\" before ones you send, instead of \"whispers:\" and \"To\"."] = "받은 귓속말 앞에는 초록색 \">\", 보낸 귓속말 앞에는 빨간색 \"<\"를 표시합니다. 기존의 \"귓속말:\" 및 \"받는 사람\" 대신 사용합니다."
L["A health bar on unit tooltips, in FlareUI's look:\n* Below: under the tooltip\n* Inside: at the tooltip's bottom, which grows to hold it"] = "유닛 툴팁에 FlareUI 스타일의 생명력 바를 표시합니다.\n* 아래: 툴팁 아래쪽에 표시\n* 내부: 툴팁 하단에 표시하며, 바를 수용하도록 툴팁이 확장됩니다."
L["A key that minimizes or opens the tracker."] = "추적기를 최소화하거나 여는 키입니다."
L["A list beside the flight map. Search for a stop by name or zone, see its fare, and star the ones you use most."] = "비행 지도 옆에 목록을 표시합니다. 정류장 이름이나 지역으로 검색하고 요금을 확인할 수 있으며, 자주 이용하는 곳에는 별표를 표시할 수 있습니다."
L["A little more space between chat lines."] = "채팅 줄 사이의 간격을 조금 더 넓힙니다."
L["A loot window, loot rolls and a loot feed"] = "전리품 창, 전리품 주사위 굴림 및 전리품 알림"
L["A Meter tab beside your chat tabs shows the meter inside the chat window. Pick when it opens on its own; tick as many as you like:\n* Open When Clicked: only when you click it\n* Open in Combat: during fights, back to the chat after\n* Open in a Group: while you're in a group\n* Open at Login: it starts open"] = "채팅 탭 옆의 측정기 탭을 누르면 채팅 창 안에 측정기가 표시됩니다. 측정기가 자동으로 열릴 시점을 선택하세요. 원하는 항목을 여러 개 선택할 수 있습니다.\n* 클릭할 때 열기: 탭을 클릭했을 때만 엽니다.\n* 전투 중 열기: 전투 중에 열고, 전투가 끝나면 채팅으로 돌아갑니다.\n* 파티에 있을 때 열기: 파티에 속해 있는 동안 엽니다.\n* 로그인할 때 열기: 로그인하면 열린 상태로 시작합니다."
L["A minimap with square and round styles."] = "사각형 및 원형 스타일을 지원하는 미니맵입니다."
L["A new one hides on every frame. Its row below can change it to Show and pick the frames."] = "새 항목은 모든 프레임에서 숨김으로 설정됩니다. 아래쪽 행에서 표시로 변경하고 적용할 프레임을 선택할 수 있습니다."
L["A new radial starts on this character only."] = "새 원형 메뉴는 현재 캐릭터에서만 사용할 수 있습니다."
L["A newly learned rank replaces the lower rank on your bars."] = "새로운 등급을 배우면 행동 단축바의 낮은 등급 주문을 대체합니다."
L["A note icon in each chat window's top right corner. Click it to copy that window's lines."] = "각 채팅 창의 오른쪽 위 모서리에 메모 아이콘을 표시합니다. 클릭하면 해당 창의 대화 내용을 복사합니다."
L["A paw marks the food your hunter pet eats."] = "발바닥 아이콘으로 사냥꾼 소환수가 먹는 음식을 표시합니다."
L["A quest mark beside the plate on enemies your quests need. It sits on the side away from the level, or on the right with no level beside the bar."] = "퀘스트에 필요한 적의 이름표 옆에 퀘스트 표시를 추가합니다. 레벨 표시가 있으면 레벨의 반대쪽에, 바 옆에 레벨이 없으면 오른쪽에 표시됩니다."
L["A quest you accept doesn't take the focus. The quest you had focused stays focused."] = "새로 수락한 퀘스트가 주시 퀘스트를 차지하지 않습니다. 기존에 주시하던 퀘스트가 계속 주시 상태로 유지됩니다."
L["A red line on the Threat tab's bars, where you would pull the enemy off the tank."] = "위협 수준 탭의 바에 빨간 선을 표시합니다. 이 선은 방어 담당자에게서 적의 주의를 빼앗게 되는 지점을 나타냅니다."
L["A ring of spells, items, macros and more. Hold the key, point, release."] = "주문, 아이템, 매크로 등을 담는 원형 메뉴입니다. 키를 누른 채 원하는 항목을 가리킨 다음 놓으세요."
L["A roll you pass on leaves the window. The icon at the top opens Blizzard's loot history. Placed and scaled in Edit Mode as \"FlareUI Loot Rolls\"."] = "포기한 주사위 굴림은 창에서 사라집니다. 상단의 아이콘을 누르면 블리자드 전리품 기록이 열립니다. 편집 모드에서 \"FlareUI Loot Rolls\"로 위치와 크기를 조정할 수 있습니다."
L["A short rumble when a spell lights up on your action bars."] = "행동 단축바의 주문이 활성화될 때 짧은 진동을 발생시킵니다."
L["A short tag after the quest name:\n* + for elite\n* g3 for a group of 3\n* d for dungeon, r for raid\n* pvp for PvP"] = "퀘스트 이름 뒤에 짧은 표시를 추가합니다.\n* +: 정예\n* g3: 3인 그룹\n* d: 던전, r: 공격대\n* pvp: PvP"
L["A short time in blue before each message, like <12:30>."] = "각 메시지 앞에 <12:30>과 같은 짧은 시간을 파란색으로 표시합니다."
L["A small frame for each pet, under its owner."] = "각 소환수의 주인 아래에 작은 프레임을 표시합니다."
L["A small frame for each pet: under its owner, or beside it."] = "각 소환수를 위한 작은 프레임을 표시합니다. 주인 아래 또는 옆에 배치할 수 있습니다."
L["A soft glow round your target's plate and its level, in the bar's own colour."] = "대상의 이름표와 레벨 주위에 바 자체의 색상으로 은은한 빛을 표시합니다."
L["A sound as Pull Warning starts, so you hear it without watching the meter."] = "공격 시작 경고가 시작될 때 소리를 재생하므로 측정기를 보고 있지 않아도 알 수 있습니다."
L["A sound when a reminder appears. Picking one plays it."] = "알림이 나타날 때 소리를 재생합니다. 소리를 선택하면 미리 재생됩니다."
L["A sound when someone whispers you. Picking one plays it."] = "누군가 귓속말을 보내면 소리를 재생합니다. 소리를 선택하면 미리 재생됩니다."
L["A spark crosses the bar during the global cooldown."] = "전역 재사용 대기시간 동안 바를 가로지르는 섬광을 표시합니다."
L["A spark crosses the bar for five seconds after you spend mana. Spirit regeneration starts again when it ends."] = "마나를 소비한 후 5초 동안 바를 가로지르는 섬광을 표시합니다. 섬광이 사라지면 정신력에 의한 마나 재생이 다시 시작됩니다."
L["A spell or buff to keep up: its name or spell ID. Several, separated by commas, count as one (any of them). An item: item:ID."] = "유지할 주문 또는 강화 효과의 이름이나 주문 ID를 입력하세요. 쉼표로 구분해 여러 개를 입력하면 하나의 항목으로 취급되며, 그중 하나만 유지해도 됩니다. 아이템은 item:ID 형식으로 입력하세요."
L["A tab that shows several kinds keeps your current one. A Party or Raid tab sets Say while you're not in one."] = "여러 종류를 표시하는 탭은 현재 선택된 채팅 종류를 유지합니다. 파티나 공격대에 속해 있지 않을 때 파티 또는 공격대 탭을 선택하면 대화 채널이 일반 대화로 설정됩니다."
L["A Threat Within"] = "내부의 위협"
L["A timer for each weapon's next swing."] = "각 무기의 다음 공격까지 남은 시간을 표시합니다."
L["A Train All button at class and profession trainers."] = "직업 및 전문 기술 상급자에게 모두 배우기 버튼을 추가합니다."
L["A Train All button at trainers"] = "상급자에게 모두 배우기 버튼 추가"
L["A weapon's or armour's item level at the bottom of its tooltip."] = "무기 또는 방어구 툴팁 하단에 아이템 레벨을 표시합니다."
L["Abilities glow when they become usable or a proc buff empowers them:\n* Overpower, Execute, Hammer of Wrath and more\n* Ice Lance with Fingers of Frost"] = "능력을 사용할 수 있게 되거나 발동형 강화 효과로 능력이 강화되면 빛을 표시합니다.\n* 제압, 마무리 일격, 응징의 격노 등\n* 얼음창과 서리의 손가락"
L["About"] = "정보"
L["Above"] = "위"
L["Above the Frame"] = "프레임 위"
L["Above the Frame, Left"] = "프레임 위, 왼쪽"
L["Above the Frame, Right"] = "프레임 위, 오른쪽"
L["Above the Tank"] = "방어 담당자보다 높음"
L["Absorb Texture"] = "흡수 효과 텍스처"
L["Accept Resurrections"] = "부활 수락"
L["Accept Summons"] = "소환 수락"
L["Action Bar 1"] = "행동 단축바 1"
L["Action Bar 2"] = "행동 단축바 2"
L["Action Bar 3"] = "행동 단축바 3"
L["Action Bar 4"] = "행동 단축바 4"
