L["Bars and frames in the same fade group:\n* Fade together\n* Share their Visibility, Show Speed, Hide Speed and Faded Opacity"] = "같은 페이드 그룹에 속한 바와 프레임은 다음과 같이 작동합니다.\n* 함께 페이드됩니다.\n* 표시 여부, 표시 속도, 숨김 속도 및 페이드 상태 불투명도를 공유합니다."
