L["Below the Map"] = "지도 아래"
L["Below this much health, the bar turns the execute colour. A thin line marks where it starts. Automatic uses your class's own, such as a warrior's Execute or a paladin's Hammer of Wrath."] = "생명력이 이 수치 아래로 내려가면 바가 마무리 공격 색상으로 바뀝니다. 얇은 선으로 해당 구간의 시작점을 표시합니다. 자동 설정은 전사의 마무리 일격이나 성기사의 응징의 격노처럼 직업 고유의 능력을 기준으로 합니다."
L["Better NPC Names"] = "NPC 이름 개선"
L["Better Player Names"] = "플레이어 이름 개선"
L["Better Timestamps"] = "시간 표시 개선"
L["Big"] = "크게"
L["Big defensives on the unit, its own or ones others put on it, left of the plate."] = "유닛 자신이나 다른 사람이 해당 유닛에게 사용한 주요 방어 효과를 이름표 왼쪽에 크게 표시합니다."
L["Binds when picked up"] = "획득 시 단축키 지정"
L["Blessing"] = "축복"
L["Blizzard"] = "블리자드"
L["Blizzard Frames"] = "블리자드 프레임"
L["Blizzard limits which auras can be filtered. If one here doesn't hide or show, this is why:\n* Allowed: buffs on you, your pet and your group, and debuffs on enemies.\n* Blocked: debuffs on you or a friend, except a few harmless ones such as Sated.\nA debuff marked Not on You is one of those: it still hides on enemies."] = "블리자드는 필터링할 수 있는 오라의 종류를 제한합니다. 여기서 어떤 오라가 숨겨지거나 표시되지 않는다면 그 이유는 다음과 같습니다.\n* 허용: 자신, 소환수 및 파티원의 강화 효과와 적의 약화 효과\n* 차단: 자신이나 아군에게 걸린 약화 효과. 포만감과 같은 일부 무해한 효과는 예외입니다.\n'자신에게 적용되지 않음'으로 표시된 약화 효과는 이 제한에 해당하지만, 적에게 걸린 경우에는 여전히 숨길 수 있습니다."
L["Blizzard's action bars in FlareUI's style."] = "블리자드 행동 단축바에 FlareUI 스타일을 적용합니다."
L["Blizzard's bars, sharpened: red when out of range, blue with no mana, glows on procs."] = "블리자드 바를 개선합니다. 사거리 밖에서는 빨간색, 마나가 부족하면 파란색으로 표시하고, 발동 효과가 발생하면 빛납니다."
L["Blizzard's bronze frame and portrait ring."] = "블리자드의 청동색 프레임과 초상화 테두리입니다."
L["Blizzard's Cooldown Manager in FlareUI's style."] = "블리자드 재사용 대기시간 관리자에 FlareUI 스타일을 적용합니다."
L["Blizzard's damage meter in a FlareUI frame, with a threat view."] = "블리자드 피해량 측정기를 위협 수준 보기 기능과 함께 FlareUI 프레임에 표시합니다."
L["Blizzard's damage meter is off. FlareUI's meter needs it."] = "블리자드 피해량 측정기가 꺼져 있습니다. FlareUI 측정기를 사용하려면 해당 기능이 필요합니다."
L["Blizzard's own text takes the Global Font too: menus, windows, quest text, nameplates, combat text and more. Sizes and outlines stay as they are."] = "메뉴, 창, 퀘스트 텍스트, 이름표, 전투 텍스트 등 블리자드 자체 텍스트에도 전역 글꼴을 적용합니다. 크기와 윤곽선은 기존 설정을 유지합니다."
L["Blizzard's own Visibility for the damage meter is set to In a Group or Hidden, so it will hide the meter when a fight starts.\n\nOpen Edit Mode, click the Damage Meter and set its Visibility to Always. FlareUI's own Visibility then decides when it shows."] = "블리자드 자체 피해량 측정기의 표시 여부가 '파티에 있을 때' 또는 '숨김'으로 설정되어 있어 전투가 시작되면 측정기가 숨겨집니다.\n\n편집 모드를 열고 피해량 측정기를 클릭한 다음 표시 여부를 '항상'으로 설정하세요. 그러면 FlareUI의 표시 여부 설정에 따라 측정기가 표시됩니다."
L["Blizzard's own Visibility for the meter, in Edit Mode, hides it at the start of some fights, and FlareUI can't bring it back until the fight ends. Set it to Always there and let FlareUI's Visibility decide."] = "편집 모드에서 설정한 블리자드 자체 측정기의 표시 여부 때문에 일부 전투가 시작될 때 측정기가 숨겨질 수 있으며, 전투가 끝날 때까지 FlareUI가 다시 표시할 수 없습니다. 해당 설정을 '항상'으로 변경하고 FlareUI의 표시 여부 설정에 맡기세요."
L["Blizzard's slot frame on every button of bars 1 to 8 and the pet bar, even where a bar hides its art."] = "바의 그래픽이 숨겨진 경우에도 1~8번 바와 소환수 바의 모든 버튼에 블리자드 슬롯 프레임을 표시합니다."
L["BoE"] = "착용 시 귀속"
L["BoE Text"] = "착용 시 귀속 텍스트"
L["Border"] = "테두리"
L["Border shows with Modern only."] = "테두리는 Modern 스타일에서만 표시됩니다."
L["Border shows with Modern only. Inside the chat (Meter Tab in the Chat), the chat's frame is the meter's."] = "테두리는 Modern 스타일에서만 표시됩니다. 채팅 내부(채팅의 측정기 탭)에서는 채팅 프레임이 측정기의 프레임으로 사용됩니다."
L["Borderless Micro Menu"] = "테두리 없는 마이크로 메뉴"
L["Boss"] = "우두머리"
L["Boss Frames"] = "우두머리 프레임"
