L["Category Rows need the combined backpack. In a narrow backpack or separate bags, the filters sit in a drawer. Click the lit filter again, or right-click it, to clear it."] = "범주 행을 사용하려면 통합 가방이 필요합니다. 좁은 가방이나 개별 가방을 사용하는 경우 필터는 서랍에 표시됩니다. 켜져 있는 필터를 다시 클릭하거나 오른쪽 클릭하면 선택이 해제됩니다."
