L["Changing Sundial reloads the interface. Without it, a drawer that opened from the sundial opens from Blizzard's small addon button instead."] = "Sundial을 변경하면 인터페이스가 다시 불러와집니다. Sundial이 없으면 Sundial에서 열리던 서랍은 대신 블리자드의 작은 애드온 버튼을 통해 열립니다."
L["Changing this setting requires a UI Reload to prevent layout issues."] = "레이아웃 문제를 방지하려면 이 설정을 변경한 후 UI를 다시 불러와야 합니다."
