L["Choose a key for your Radial Menu (the page opens after the reload)"] = "원형 메뉴에 사용할 키를 선택하세요. 다시 불러온 후 해당 설정 페이지가 열립니다."
L["Choose one:"] = "하나를 선택하세요:"
L["Cities and battlegrounds have no range."] = "도시와 전장에서는 사거리 제한이 없습니다."
