L["clash"] = "충돌"
L["Class"] = "직업"
L["Class & Reaction"] = "직업 및 반응"
L["Class Buffs"] = "직업 강화 효과"
L["Class buffs you're reminded of only if you tick them: Shadow Protection and Moonkin Form."] = "선택한 직업 강화 효과만 알림을 표시합니다. 해당 효과에는 어둠의 보호와 달빛야수 변신이 있습니다."
L["Class Colours"] = "직업 색상"
L["Class Default"] = "직업 기본값"
L["Class Icon"] = "직업 아이콘"
L["Class Icons"] = "직업 아이콘"
L["Class-Coloured Names"] = "직업별 색상 이름"
L["Classic"] = "클래식"
L["Classic: Blizzard's combo point gems. Modern: a bar split into points, which takes the Combo Points colour."] = "클래식: 블리자드의 연계 점수 보석을 사용합니다. 모던: 연계 점수 색상이 적용된 바를 점수 단위로 나누어 표시합니다."
L["Classic: gems round the portrait. Modern: a bar along the top of the health bar, as in Modern Style."] = "클래식: 초상화 둘레에 보석을 표시합니다. 모던: 모던 스타일처럼 생명력 바 위쪽을 따라 바 형태로 표시합니다."
L["Classic: the player frame's look. Raid Style: compact tiles with the auras inside. Each style keeps its own settings."] = "클래식: 플레이어 프레임의 외형을 사용합니다. 공격대 스타일: 오라를 내부에 표시하는 작은 타일 형태를 사용합니다. 각 스타일은 자체 설정을 유지합니다."
L["Cleaner tooltips with coloured borders that can follow your mouse."] = "마우스를 따라다니며 색상 테두리로 표시되는 깔끔한 툴팁입니다."
L["Cleaner tooltips with coloured borders."] = "색상 테두리로 더 깔끔해진 툴팁입니다."
L["Clear All Markers"] = "모든 징표 지우기"
L["Clear Player Choices (%d)"] = "플레이어 선택 초기화 (%d)"
L["Clear Target's Marker"] = "대상의 징표 지우기"
L["Clear World Markers"] = "세계 징표 지우기"
L["Clears the meter when you enter a new dungeon or raid."] = "새로운 던전이나 공격대에 입장하면 측정기를 초기화합니다."
L["Clears the meter when you leave a party or raid."] = "파티나 공격대에서 나가면 측정기를 초기화합니다."
L["Click |cffffd100Copy Layout Code|r and press |cffffd100Ctrl+C|r."] = "|cffffd100레이아웃 코드 복사|r를 클릭한 다음 |cffffd100Ctrl+C|r를 누르세요."
L["Click a button to copy its link"] = "버튼을 클릭하면 해당 링크를 복사합니다."
L["Click a chat tab to get the chat back, in combat too. A tab you click stays up until the condition changes, like a fight ending."] = "채팅 탭을 클릭하면 전투 중에도 채팅이 다시 표시됩니다. 클릭한 탭은 전투 종료처럼 조건이 변경될 때까지 계속 표시됩니다."
L["Click a colour to change it; right-click gives it back to the palette."] = "색상을 클릭하면 변경할 수 있으며, 오른쪽 클릭하면 팔레트의 기본 색상으로 되돌립니다."
L["Click a FlareUI frame to see its options"] = "FlareUI 프레임을 클릭하면 해당 옵션이 표시됩니다."
L["Click again to clear the filter."] = "다시 클릭하면 필터가 해제됩니다."
L["Click or drag from Catalog to add. Drag reorders, right-click removes."] = "목록에서 클릭하거나 드래그하여 추가하세요. 드래그하면 순서가 변경되고, 오른쪽 클릭하면 제거됩니다."
L["Click or drag to add it."] = "클릭하거나 드래그하여 추가하세요."
L["Click to go to this setting."] = "클릭하면 해당 설정으로 이동합니다."
L["Click to open or close. Right-click to rename or ungroup. Drag to move."] = "클릭하면 열거나 닫습니다. 오른쪽 클릭하면 이름을 변경하거나 그룹을 해제합니다. 드래그하면 이동합니다."
L["Click to switch"] = "클릭하여 전환"
L["Click-Through"] = "클릭 통과"
L["Click: next sort. Right-click: the one before."] = "클릭: 다음 정렬 방식. 오른쪽 클릭: 이전 정렬 방식."
L["Click: pick a colour. Right-click: the palette's own."] = "클릭: 색상 선택. 오른쪽 클릭: 팔레트의 기본 색상으로 되돌리기."
