L["Debuffs above the bar, from its right end (centred with Buffs off). Tick filters to narrow them down; each one you tick must match:\n* Only Mine: the ones you put on it\n* Only Dispellable: the ones you can dispel"] = "바의 오른쪽 끝부터 위쪽에 약화 효과를 표시합니다. 강화 효과 표시를 끄면 가운데 정렬됩니다. 필터를 선택해 표시 대상을 좁힐 수 있으며, 선택한 필터는 모두 충족해야 합니다.\n* 내 효과만: 자신이 대상에게 적용한 효과\n* 해제 가능한 효과만: 자신이 해제할 수 있는 효과"
L["Debuffs as Blizzard's raid frames pick them: boss and role debuffs, priority debuffs, and the ones you can dispel."] = "블리자드 공격대 프레임에서 선택하는 방식으로 약화 효과를 표시합니다. 우두머리 및 역할별 약화 효과, 우선순위 약화 효과와 자신이 해제할 수 있는 효과가 표시됩니다."
L["Debuffs on the boss. With Only My Debuffs, just yours."] = "우두머리에게 적용된 약화 효과를 표시합니다. 내 약화 효과만 설정을 사용하면 자신이 적용한 효과만 표시합니다."
