L["Default: yours first, then the important ones. Time Left: the soonest to end first."] = "기본값: 자신의 효과를 먼저 표시한 다음 중요한 효과를 표시합니다. 남은 시간순: 종료 시간이 가장 빠른 효과부터 표시합니다."
