L["Each bank bag starts a new row in the bank, with a gap above it."] = "은행에서 각 은행 가방은 위쪽에 간격을 두고 새로운 행에서 시작합니다."
L["Each bar's size, buttons, rows and fading are set in Edit Mode."] = "각 바의 크기, 버튼, 행 및 페이드 설정은 편집 모드에서 지정합니다."
L["Each bar's size, text and visibility are set in Edit Mode."] = "각 바의 크기, 텍스트 및 표시 여부는 편집 모드에서 지정합니다."
L["Each character keeps its own choice. Switching profiles reloads the interface."] = "각 캐릭터는 고유한 선택 설정을 유지합니다. 프로필을 전환하면 인터페이스가 다시 불러와집니다."
L["Each Edit Mode layout keeps its own Scale."] = "각 편집 모드 레이아웃은 고유한 크기 비율을 유지합니다."
L["Each Font's Own"] = "각 글꼴 고유 설정"
