L["Emotes"] = "감정 표현"
L["Empty slots stay bronze, and every border is bronze with Colour by Rarity off."] = "빈 슬롯은 청동색으로 유지되며, 희귀도별 색상 설정을 끄면 모든 테두리가 청동색으로 표시됩니다."
L["Enable Blizzard Cooldown Manager"] = "블리자드 재사용 대기시간 관리자 활성화"
L["Enemy"] = "적"
L["Enemy and friendly players and NPCs each have their own look"] = "적대적인 플레이어와 NPC, 우호적인 플레이어와 NPC는 각각 고유한 외형을 사용합니다."
L["Enemy Minions"] = "적대적 소환수"
L["Enemy NPC"] = "적대적 NPC"
L["Enemy NPCs you can't attack yet show only their name. Their full plate comes back once you can attack them."] = "아직 공격할 수 없는 적대적 NPC는 이름만 표시됩니다. 공격할 수 있게 되면 이름표 전체가 다시 표시됩니다."
L["Enemy Player"] = "적대적 플레이어"
L["Enemy Players"] = "적대적 플레이어"
L["Enemy Types"] = "적 유형"
L["Enhanced Vendor Purchases"] = "상인 구매 기능 강화"
L["Enter: go to the first"] = "Enter: 첫 번째 항목으로 이동"
L["Equipment"] = "장비"
L["Equipped"] = "장착됨"
L["Equipped Item Border"] = "장착 아이템 테두리"
L["Error log cleared."] = "오류 기록을 지웠습니다."
L["Error Messages"] = "오류 메시지"
L["Errors FlareUI caught, to copy into a bug report (\"/fui errors clear\" empties the list)."] = "FlareUI가 감지한 오류입니다. 버그 보고서에 복사할 수 있습니다. (\"/fui errors clear\" 명령어로 목록을 비울 수 있습니다.)"
L["ESC Menu"] = "ESC 메뉴"
L["Every addon's minimap button in one drawer. Click the day/night badge to open it."] = "모든 애드온의 미니맵 버튼을 하나의 서랍에 모읍니다. 낮/밤 표시를 클릭하면 서랍이 열립니다."
L["Every buff on the boss, such as enrages and shields."] = "격노와 보호막 등 우두머리에게 적용된 모든 강화 효과입니다."
L["Every colour the plates paint, next to sample plates:\n* Reaction and tapped\n* Threat, as a tank and as damage or healer\n* Cast bar, target border, heals and shields\nChange any colour and the palette becomes Custom."] = "예시 이름표 옆에서 이름표에 사용되는 모든 색상을 확인할 수 있습니다.\n* 반응 및 공격받는 대상\n* 방어 담당자와 공격 담당자 또는 치유 담당자 기준의 위협 수준\n* 시전 바, 대상 테두리, 치유 및 보호막\n색상을 하나라도 변경하면 팔레트가 사용자 지정으로 전환됩니다."
L["Every colour the XP bar paints, next to a sample bar:\n* XP, Rested XP, Rested Bonus, Quest XP\n* Reputation by standing, and Renown\n* Honor\nChange any colour and the palette becomes Custom."] = "예시 바 옆에서 경험치 바에 사용되는 모든 색상을 확인할 수 있습니다.\n* 경험치, 휴식 경험치, 휴식 보너스, 퀘스트 경험치\n* 평판 등급별 평판 및 명성\n* 명예\n색상을 하나라도 변경하면 팔레트가 사용자 지정으로 전환됩니다."
L["Every empty slot in the combined backpack looks the same, instead of showing its bag's picture."] = "통합 가방의 모든 빈 슬롯을 가방 그림 대신 동일한 모양으로 표시합니다."
L["Every key that opens a radial on the character you're playing."] = "현재 플레이 중인 캐릭터에서 원형 메뉴를 여는 모든 키입니다."
L["Every module of this addon starts switched off.\nTo begin, open the settings and enable the modules you want to use."] = "이 애드온의 모든 모듈은 처음에 비활성화되어 있습니다.\n시작하려면 설정을 열고 사용할 모듈을 활성화하세요."
L["Every other character copies its settings from this one."] = "다른 모든 캐릭터가 이 캐릭터의 설정을 복사합니다."
L["Every other line."] = "한 줄씩 건너뛰어 표시"
L["Every resource bar colour in one window, next to the bars. Palettes:\n* FlareUI (default)\n* Blizzard"] = "각 자원 바 옆에서 모든 자원 바 색상을 하나의 창에 표시합니다. 팔레트:\n* FlareUI (기본값)\n* 블리자드"
L["Every unit frame colour in one window, next to the frames. Palettes:\n* FlareUI: softer, darker tones (default)\n* Blizzard: the game's own"] = "각 유닛 프레임 옆에서 모든 유닛 프레임 색상을 하나의 창에 표시합니다. 팔레트:\n* FlareUI: 더 부드럽고 어두운 색조 (기본값)\n* 블리자드: 게임 기본 색상"
L["Everyone"] = "모두"
L["Everyone passed"] = "모두 포기했습니다."
L["Everything Else"] = "기타 모든 항목"
L["Everything starts switched off. This short tour shows you what each part does, and you choose the ones you want as you go."] = "모든 기능은 처음에 비활성화되어 있습니다. 이 짧은 안내를 통해 각 기능을 살펴보고 원하는 기능을 선택할 수 있습니다."
L["Everything you need, one key away."] = "필요한 모든 기능을 키 하나로 이용하세요."
L["Everywhere"] = "모든 곳"
L["Execute Range"] = "처치 가능 사거리"
