L["Extra health, power, combo point and swing bars to place anywhere. Off to begin with: choose your bars in /fui."] = "원하는 위치에 배치할 수 있는 추가 생명력, 자원, 연계 점수 및 무기 공격 속도 바입니다. 처음에는 비활성화되어 있으므로 /fui에서 사용할 바를 선택하세요."
L["Extras"] = "추가 기능"
