L["Finished objectives stay on the list."] = "완료한 목표도 목록에 계속 표시됩니다."
L["Finished quests are turned in when you talk to the NPC. Some always wait for you: repeatable and daily quests, a reward to choose, a gold cost, or battleground marks to hand in."] = "완료한 퀘스트는 NPC와 대화하면 자동으로 반납됩니다. 단, 반복 퀘스트와 일일 퀘스트, 선택해야 할 보상이 있는 퀘스트, 골드가 필요한 퀘스트, 반납할 전장 훈장이 있는 퀘스트는 자동 반납되지 않습니다."
L["Finished quests get a green \"(Complete)\" after their name."] = "완료한 퀘스트 이름 뒤에 초록색 \"(완료)\"가 표시됩니다."
L["First Name"] = "이름"
L["Fishing Sounds"] = "낚시 소리"
L["Five-Second Rule"] = "5초 규칙"
L["Flag Carrier Frames"] = "깃발 운반자 프레임"
L["Flag Carriers"] = "깃발 운반자"
L["FlareUI"] = "FlareUI"
L["FlareUI Buffs"] = "FlareUI 강화 효과"
L["FlareUI Button"] = "FlareUI 버튼"
L["FlareUI caught errors"] = "FlareUI가 오류를 감지했습니다."
L["FlareUI copied this character's interface settings from %s.\n\nReload now to finish applying them. Until you do, some of Blizzard's own panels - Edit Mode in particular - can throw errors."] = "FlareUI가 이 캐릭터의 인터페이스 설정을 %s에서 복사했습니다.\n\n설정을 완전히 적용하려면 지금 다시 불러오세요. 다시 불러오기 전까지 블리자드의 일부 패널, 특히 편집 모드에서 오류가 발생할 수 있습니다."
L["FlareUI Debuffs"] = "FlareUI 약화 효과"
L["FlareUI Edit Mode Layout"] = "FlareUI 편집 모드 레이아웃"
L["FlareUI is the default. Change any colour and it becomes Custom. Apply keeps your choice."] = "FlareUI가 기본값입니다. 색상을 하나라도 변경하면 사용자 지정으로 전환됩니다. 적용을 누르면 선택한 설정이 유지됩니다."
L["FlareUI Loot Feed"] = "FlareUI 전리품 알림"
L["FlareUI Loot Rolls"] = "FlareUI 전리품 주사위"
L["FlareUI Loot Window"] = "FlareUI 전리품 창"
L["FlareUI Minimap Button"] = "FlareUI 미니맵 버튼"
L["FlareUI Settings"] = "FlareUI 설정"
L["FlareUI starts %s after a reload."] = "다시 불러오면 FlareUI가 %s 상태로 시작합니다."
L["FlareUI Style"] = "FlareUI 스타일"
L["FlareUI Thick"] = "FlareUI 두꺼운 테두리"
L["FlareUI Thin"] = "FlareUI 얇은 테두리"
L["FlareUI's border in place of the bronze frame on every bar's buttons: main, pet, stance, possess, totem and vehicle bars. Only the border changes."] = "주 행동 단축바, 소환수, 태세, 빙의, 토템 및 탈것 바의 모든 버튼에 청동색 테두리 대신 FlareUI 테두리를 사용합니다. 테두리만 변경됩니다."
L["FlareUI's border round each bag slot:\n* Off: Blizzard's own slots, for example when another addon skins your bags\n* Thin Borders: a thin border\n* Thick Borders: a thicker frame\n* Colour by Rarity: the border in the item's quality colour"] = "각 가방 슬롯에 FlareUI 테두리를 적용합니다.\n* 끄기: 블리자드 기본 슬롯을 사용합니다. 예를 들어 다른 애드온이 가방 외형을 변경하는 경우에 적합합니다.\n* 얇은 테두리: 얇은 테두리를 사용합니다.\n* 두꺼운 테두리: 더 두꺼운 테두리를 사용합니다.\n* 희귀도별 색상: 아이템 품질에 해당하는 색상의 테두리를 사용합니다."
L["FlareUI's files didn't load completely. Restart the game. If this keeps happening, reinstall FlareUI."] = "FlareUI 파일이 완전히 불러와지지 않았습니다. 게임을 다시 시작하세요. 문제가 계속되면 FlareUI를 다시 설치하세요."
L["FlareUI's look and keybinds for Blizzard's Cooldown Manager: pick them in /fui. Turning it on here turns Blizzard's on too."] = "블리자드 재사용 대기시간 관리자의 FlareUI 외형과 단축키를 /fui에서 설정하세요. 여기서 활성화하면 블리자드 재사용 대기시간 관리자도 함께 활성화됩니다."
L["FlareUI's look on the Cooldown Manager:\n* Tracked Bars like FlareUI's cast bars\n* Icons with FlareUI's borders"] = "재사용 대기시간 관리자에 FlareUI 외형을 적용합니다.\n* 추적 바: FlareUI 시전 바와 같은 스타일\n* 아이콘: FlareUI 테두리 적용"
L["FlareUI's loot roll window replaces Blizzard's roll frames:\n* Need, Greed and Pass for each item\n* Everyone's choice and roll as they come in\n* Who leads, then who won"] = "FlareUI 전리품 주사위 창이 블리자드의 주사위 프레임을 대체합니다.\n* 각 아이템에 대해 차비, 입찰 및 포기를 선택할 수 있습니다.\n* 모든 플레이어의 선택과 주사위 결과를 실시간으로 표시합니다.\n* 현재 선두와 최종 승자를 표시합니다."
L["FlareUI's loot window replaces Blizzard's for corpses and chests:\n* How many of each item you already carry\n* The marks from your bags (item level, junk, BoE), as set on the Bags tab\n* A looted item leaves a gap, so nothing moves under your mouse"] = "FlareUI 전리품 창이 시체와 상자에서 블리자드 전리품 창을 대체합니다.\n* 각 아이템을 이미 몇 개 가지고 있는지 표시합니다.\n* 가방 탭에서 설정한 표시(아이템 레벨, 잡동사니, 착용 시 귀속)를 적용합니다.\n* 전리품을 획득한 자리에 빈 공간을 남겨 마우스 아래의 아이템이 움직이지 않도록 합니다."
L["FlareUI's own button, for opening these settings. While Drawer Style isn't Off, it sits in the drawer."] = "이 설정 창을 열기 위한 FlareUI 전용 버튼입니다. 서랍 스타일이 끄기로 설정되지 않은 경우 서랍 안에 표시됩니다."
L["FlareUI's own frames already sit where the layout expects them"] = "FlareUI 전용 프레임은 이미 레이아웃에서 지정한 위치에 배치되어 있습니다."
L["FlareUI's own nameplates, for enemies and friends."] = "적과 아군을 위한 FlareUI 전용 이름표입니다."
L["FlareUI's own quest tracker."] = "FlareUI 전용 퀘스트 추적기입니다."
L["FlareUI's XP bar, with your watched reputation or honor:\n* Off: Blizzard's bars\n* Single: one bar, XP (reputation or honor at max level)\n* Split: XP and reputation side by side\n* Double: two bars, the second below the first"] = "추적 중인 평판 또는 명예를 함께 표시하는 FlareUI 경험치 바입니다.\n* 끄기: 블리자드 기본 바를 사용합니다.\n* 단일: 하나의 바를 표시합니다. 경험치 또는 만렙에서 평판이나 명예를 표시합니다.\n* 분할: 경험치와 평판을 나란히 표시합니다.\n* 이중: 두 개의 바를 표시하며, 두 번째 바는 첫 번째 바 아래에 배치됩니다."
L["Flash When Targeted"] = "대상이 되면 깜박임"
L["Flashes the taskbar and plays a sound for:\n* Ready checks\n* Summons and resurrections\n* Group invites\n* Dungeon queues"] = "다음 상황에서 작업 표시줄을 깜박이고 소리를 재생합니다.\n* 전투 준비 확인\n* 소환 및 부활\n* 파티 초대\n* 던전 대기열"
L["Flask"] = "영약"
L["Flight Destination List"] = "비행 목적지 목록"
L["Flight time: %s"] = "비행 시간: %s"
L["Flight Timer"] = "비행 타이머"
L["Flip Portrait"] = "초상화 뒤집기"
L["Flips the frame to face the player frame. In FlareUI and Forever Style, only the bars flip."] = "플레이어 프레임을 향하도록 프레임을 뒤집습니다. FlareUI 및 Forever 스타일에서는 바만 뒤집힙니다."
L["Focus"] = "주시 대상"
L["Focus Button"] = "주시 대상 버튼"
L["Focus Colour"] = "주시 대상 색상"
