L["For every character."] = "모든 캐릭터에 적용"
L["For example: /way 45 60 or /way Elwynn Forest 45 60."] = "예: /way 45 60 또는 /way Elwynn Forest 45 60"
L["For example: one group for your bottom bars, another for your side bars."] = "예: 하단 바를 위한 그룹 하나와 측면 바를 위한 그룹 하나를 만들 수 있습니다."
L["For some casts Blizzard says \"can't interrupt\" when you actually can."] = "일부 주문은 실제로 차단할 수 있는데도 블리자드에서 \"차단할 수 없음\"이라고 표시합니다."
