L["Forest Spider"] = "숲거미"
L["Forever"] = "Forever"
L["Forever Style"] = "Forever 스타일"
L["ForeverFarmHUD and FarmHud move the minimap into their HUD while it is on. FlareUI puts its own minimap back when you turn the HUD off; if it still looks wrong, type /reload."] = "ForeverFarmHUD와 FarmHud는 활성화되어 있는 동안 미니맵을 자체 HUD 안으로 이동합니다. HUD를 끄면 FlareUI가 자체 미니맵을 원래대로 되돌립니다. 그래도 표시가 이상하다면 /reload를 입력하세요."
L["Formatting"] = "서식"
