L["Friz Quadrata TT (Crisp) is Blizzard's sharper copy of the game font. It lacks a few symbols, so some show as boxes (the dot in \"Honored · -10%\", for one)."] = "Friz Quadrata TT (Crisp)는 블리자드 게임 글꼴을 더 선명하게 만든 버전입니다. 일부 기호가 빠져 있어 몇몇 기호는 네모 상자로 표시됩니다. (예: \"우호적 · -10%\"의 가운데점)"
