L["Full Name adds the surname, Last Name shows it alone. Name Only plates have their own Show Name."] = "전체 이름은 성을 추가하고, 성은 성만 표시합니다. 이름만 표시하는 이름표에는 별도의 이름 표시 설정이 있습니다."
