L["Gamepad Mode Prompt"] = "게임패드 모드 안내"
L["Gamepad mode: puts this radial on a controller bar slot. Click, then press A, B, X, Y or the D-pad, alone or with LT, RT or both held."] = "게임패드 모드: 이 원형 메뉴를 컨트롤러 바 슬롯에 배치합니다. 클릭한 다음 A, B, X, Y 또는 방향 패드를 누르세요. LT, RT 또는 두 버튼을 함께 누른 상태에서도 사용할 수 있습니다."
L["Gamepad mode: the stick press that opens this radial. Click, then press L3 or R3, alone or with LT, RT or both held."] = "게임패드 모드: 스틱 버튼을 눌러 이 원형 메뉴를 엽니다. 클릭한 다음 L3 또는 R3을 누르세요. LT, RT 또는 두 버튼을 함께 누른 상태에서도 사용할 수 있습니다."
L["Gameplay"] = "게임플레이"
L["Gaps Between Bags"] = "가방 사이 간격"
