L["Gives every other unit frame the fonts shown below, for each text they have in common."] = "다른 모든 유닛 프레임에서 공통으로 사용하는 각 텍스트에 아래 표시된 글꼴을 적용합니다."
L["Global (%s)"] = "전체 공통 (%s)"
