L["Glow When Missing"] = "효과가 없을 때 빛나기"
L["Glow When Running Out"] = "효과가 곧 끝날 때 빛나기"
L["Gnomeregan Is Fine, Actually"] = "사실 놈리건은 괜찮습니다"
L["Go Back"] = "뒤로 가기"
L["Go Now"] = "지금 이동"
L["Gold"] = "골드"
L["Gold on This Realm"] = "이 서버의 골드"
L["Gone once your interrupt is ready. Turn on Kick Ready Colour to colour the bar then."] = "차단 기술을 사용할 수 있게 되면 사라집니다. 그때 바의 색상을 변경하려면 차단 준비 색상을 활성화하세요."
L["Good dog. All done!"] = "착한 강아지네요. 모두 끝났습니다!"
L["Good to Know"] = "알아두면 좋은 정보"
L["Got alts? Copies one character's interface options, Edit Mode layout, chat and bag settings to your others."] = "부캐릭터가 있나요? 한 캐릭터의 인터페이스 설정, 편집 모드 레이아웃, 채팅 및 가방 설정을 다른 캐릭터에 복사합니다."
L["Greed"] = "입찰"
L["Grey items worth money show a coin all the time, not only at a vendor."] = "판매 가치가 있는 회색 아이템에 상인에게서만이 아니라 항상 동전 표시를 보여줍니다."
L["Grey Out Known Items"] = "이미 알고 있는 아이템 흐리게 표시"
L["Group"] = "그룹"
L["Group %d"] = "그룹 %d"
L["Group Buffs"] = "그룹 강화 효과"
L["Group buffs show only when no one else of your class is in the group. Blessings still show, since paladins split them."] = "그룹 강화 효과는 그룹에 같은 직업의 다른 플레이어가 없을 때만 표시됩니다. 성기사는 축복을 나누어 사용하므로 축복은 계속 표시됩니다."
L["Group Finder"] = "파티 찾기"
L["Group Gap"] = "그룹 간격"
L["Group keeps each raid group together. Role and Class fill rows of five, tanks or classes first."] = "그룹은 각 공격대 그룹을 함께 배치합니다. 역할 및 직업 정렬은 5명씩 한 행에 배치하며, 방어 담당자 또는 직업을 먼저 표시합니다."
L["Group Members"] = "그룹 구성원"
L["Group Numbers"] = "그룹 번호"
L["Group Order"] = "그룹 순서"
