L["Groups"] = "그룹"
L["Growth"] = "확장 방향"
L["Growth, icon shape and fading are set in Edit Mode."] = "확장 방향, 아이콘 모양 및 페이드 설정은 편집 모드에서 지정합니다."
L["Gryphons"] = "그리핀"
L["Guild"] = "길드"
L["Guild & Communities"] = "길드 및 커뮤니티"
L["Handy for macros and bug reports."] = "매크로와 버그 보고서 작성에 유용합니다."
L["Handy with Pixel Perfect, where text is small. Long labels may not fit above 120%."] = "텍스트가 작게 표시되는 픽셀 퍼펙트 설정과 함께 사용하면 유용합니다. 120%를 초과하면 긴 이름표가 들어가지 않을 수 있습니다."
L["Happens when the fight ends."] = "전투가 끝나면 실행됩니다."
L["Has a Target"] = "대상이 있음"
