L["Health"] = "생명력"
L["Health and power glide to their new value instead of jumping there."] = "생명력과 자원 수치가 새 값으로 즉시 바뀌지 않고 부드럽게 이동합니다."
L["Health Bar"] = "생명력 바"
L["Health bars change colour with threat:\n* In a Group: only in a party or raid. On your own, every mob attacks you anyway\n* Always: solo too"] = "위협 수준에 따라 생명력 바의 색상이 변경됩니다.\n* 그룹 내: 파티나 공격대에 있을 때만 적용됩니다. 혼자 있을 때는 모든 몬스터가 어차피 자신을 공격합니다.\n* 항상: 솔로 플레이 중에도 적용됩니다."
L["Health Lost"] = "잃은 생명력"
L["Health Max"] = "최대 생명력"
L["Health numbers show only once the unit has taken damage. The name always shows."] = "유닛이 피해를 입은 경우에만 생명력 수치를 표시합니다. 이름은 항상 표시됩니다."
L["Health Percent"] = "생명력 백분율"
L["Health Text"] = "생명력 텍스트"
L["Health Value"] = "생명력 수치"
L["Health you lose stays a moment in a light colour, then shrinks away. It isn't one of the Bar Animations."] = "잃은 생명력이 잠시 밝은 색상으로 표시된 후 줄어들며 사라집니다. 이 효과는 바 애니메이션에 포함되지 않습니다."
L["Heard even with sound effects off."] = "음향 효과를 꺼도 소리가 들립니다."
L["Height"] = "높이"
