L["Hide Pop-up Alerts"] = "팝업 알림 숨기기"
L["Hide Questie Icons"] = "Questie 아이콘 숨기기"
L["Hide Scroll Bar"] = "스크롤 바 숨기기"
L["Hide Speed"] = "숨김 속도"
L["Hide These Alerts"] = "이 알림 숨기기"
L["Hide Until Next Group"] = "다음 그룹까지 숨기기"
L["Hide Until Reload"] = "다시 불러올 때까지 숨기기"
L["Hide Value at Full Health"] = "생명력이 가득 찼을 때 수치 숨기기"
L["Hide While Mounted"] = "탈것 탑승 중 숨기기"
L["Hides Blizzard's loot toasts: items you win or loot, upgrades and money."] = "블리자드의 전리품 알림을 숨깁니다. 획득하거나 전리품으로 얻은 아이템, 장비 업그레이드 및 골드 알림이 포함됩니다."
L["Hides Blizzard's tutorial pop-ups."] = "블리자드의 튜토리얼 팝업을 숨깁니다."
L["Hides on Blizzard's frames:\n* Damage numbers on your portrait\n* Health and power numbers"] = "블리자드 프레임에서 다음 항목을 숨깁니다.\n* 초상화에 표시되는 피해량 수치\n* 생명력 및 자원 수치"
L["Hides the bag buttons."] = "가방 버튼을 숨깁니다."
L["Hides the bar shown while you control another creature."] = "다른 생명체를 조종하는 동안 표시되는 바를 숨깁니다."
L["Hides the big zone name when you enter a new area."] = "새로운 지역에 진입할 때 표시되는 큰 지역 이름을 숨깁니다."
L["Hides the raid tools on the screen's left edge."] = "화면 왼쪽 가장자리에 표시되는 공격대 도구를 숨깁니다."
L["Hides the red error text, like \"Not enough rage\"."] = "\"분노가 부족합니다\"와 같은 빨간색 오류 메시지를 숨깁니다."
L["Hides the row of menu buttons (character, spellbook, talents...)."] = "캐릭터, 주문책, 특성 등의 메뉴 버튼이 나열된 줄을 숨깁니다."
L["Hides the shaman totem bar."] = "주술사의 토템 바를 숨깁니다."
L["Hides the stance, form and aura buttons."] = "태세, 변신 형태 및 오라 버튼을 숨깁니다."
L["Hides the thin bar on the right that shows where you are in a long quest list."] = "긴 퀘스트 목록에서 현재 위치를 보여주는 오른쪽의 얇은 바를 숨깁니다."
L["Hides your pet's action bar."] = "소환수의 행동 단축바를 숨깁니다."
L["High Level Skull"] = "고레벨 해골 표시"
L["Highlight Important Casts"] = "중요한 시전 강조 표시"
L["Hogger's Tax Return"] = "호거의 세금 신고서"
L["Hold"] = "누르고 있기"
L["Hold Shift as you talk to the NPC to read the quest first."] = "NPC와 대화할 때 Shift 키를 누르고 있으면 먼저 퀘스트 내용을 확인할 수 있습니다."
L["Hold Shift as you talk to the NPC to turn it in yourself."] = "NPC와 대화할 때 Shift 키를 누르고 있으면 직접 퀘스트를 반납할 수 있습니다."
L["Hold Shift to see a hidden tooltip."] = "Shift 키를 누르고 있으면 숨겨진 툴팁을 볼 수 있습니다."
L["Hold Shift to talk normally. It never skips in dungeons or raids."] = "Shift 키를 누르고 있으면 일반적인 대화 방식으로 진행됩니다. 던전이나 공격대에서는 대화가 자동으로 건너뛰어지지 않습니다."
L["Hold Shift to talk to them as usual."] = "Shift 키를 누르고 있으면 평소처럼 대화할 수 있습니다."
L["Hold your key and a ring of buttons opens at your cursor. Point at one, let go, and it fires. It even works in combat."] = "키를 누르고 있으면 커서 위치에 버튼들이 원형으로 펼쳐집니다. 원하는 버튼을 가리킨 다음 키를 놓으면 해당 기능이 실행됩니다. 전투 중에도 사용할 수 있습니다."
L["Hold, point, release"] = "누르고, 가리키고, 놓기"
L["Honor"] = "명예"
L["Hope you enjoy FlareUI! Found a bug or have an idea? Give me a holler through the links below"] = "FlareUI를 즐겁게 사용하시길 바랍니다! 버그를 발견했거나 아이디어가 있으신가요? 아래 링크를 통해 알려주세요."
L["Horde"] = "호드"
L["Horizontal"] = "가로"
L["Hostile"] = "적대적"
L["Hover any option to see how it works!"] = "옵션 위에 마우스를 올리면 작동 방식을 확인할 수 있습니다!"
L["How a keybind opens the radial:\n* Hold: hold the key, point, release to use\n* Toggle: press to open, left-click to use; press again or right-click to close (right-click goes back from a nested radial)"] = "단축키로 원형 메뉴를 여는 방식입니다.\n* 누르고 있기: 키를 누른 채 원하는 항목을 가리킨 다음 키를 놓으면 실행됩니다.\n* 전환: 키를 눌러 열고 왼쪽 클릭으로 실행합니다. 다시 키를 누르거나 오른쪽 클릭하면 닫힙니다. (하위 원형 메뉴에서 오른쪽 클릭하면 이전 메뉴로 돌아갑니다.)"
L["How aura icons on the plates show their time left."] = "이름표의 오라 아이콘에 남은 시간을 표시하는 방식입니다."
L["How aura icons show their time left, on every unit frame."] = "모든 유닛 프레임의 오라 아이콘에 남은 시간을 표시하는 방식입니다."
L["How aura icons show their time left."] = "오라 아이콘에 남은 시간을 표시하는 방식입니다."
L["How big each buff icon is."] = "각 강화 효과 아이콘의 크기입니다."
L["How big each debuff icon is."] = "각 약화 효과 아이콘의 크기입니다."
L["How big the crowd control icon is."] = "군중 제어 아이콘의 크기입니다."
L["How big the damage and healing numbers are. It's the game's own setting."] = "피해량 및 치유량 숫자의 크기입니다. 게임 자체 설정을 사용합니다."
L["How big this unit's name is in Name Only Mode, in % of the Name Only font's size (Fonts tab)."] = "이 유닛의 이름만 표시 모드에서 이름 크기를 설정합니다. 글꼴 탭에 있는 이름만 표시 글꼴 크기에 대한 백분율로 지정합니다."
L["How channels show in chat:\n* Full: \"[1. General - Elwynn Forest]\"\n* Short: \"[1. General]\", \"[G]\" for Guild, \"[P]\" for Party\n* Number: \"[1]\", \"[G]\", \"[P]\""] = "채팅에서 채널을 표시하는 방식입니다.\n* 전체: \"[1. 일반 - 엘윈 숲]\"\n* 짧게: \"[1. 일반]\", 길드는 \"[G]\", 파티는 \"[P]\"\n* 번호: \"[1]\", \"[G]\", \"[P]\""
L["How clear the plates picked in State are. On Not Targeted, casting units and the plate under your mouse stay clear."] = "상태에서 선택한 이름표를 얼마나 투명하게 표시할지 설정합니다. 대상이 아닐 때 설정에서는 주문을 시전 중인 유닛과 마우스 아래에 있는 이름표는 선명하게 유지됩니다."
L["How dark the chat's background is."] = "채팅 배경의 어두운 정도입니다."
L["How dark the empty part of the bar is."] = "바의 비어 있는 부분을 얼마나 어둡게 표시할지 설정합니다."
L["How dark the empty part of the bars is."] = "바의 비어 있는 부분들을 얼마나 어둡게 표시할지 설정합니다."
L["How dark the meter's background is."] = "측정기 배경의 어두운 정도입니다."
L["How dark the tooltips' background is."] = "툴팁 배경의 어두운 정도입니다."
L["How dark the tracker's background is."] = "추적기 배경의 어두운 정도입니다."
L["How each plate's bar is coloured:\n* Off: Blizzard's own colours\n* Reaction: red for enemies, yellow for neutral\n* Class & Reaction: players in their class colour, everyone else by reaction\n* Health: green at full, yellow at half, red when nearly dead"] = "각 이름표 바의 색상을 지정하는 방식입니다.\n* 끄기: 블리자드 기본 색상\n* 반응: 적은 빨간색, 중립 대상은 노란색\n* 직업 및 반응: 플레이어는 직업 색상, 나머지는 반응에 따른 색상\n* 생명력: 생명력이 가득 차면 초록색, 절반이면 노란색, 거의 죽어가면 빨간색"
L["How Fake CM Works"] = "가짜 CM 작동 방식"
L["How far a mouseover tooltip sits from your mouse, down (-) or up (+), in pixels."] = "마우스를 올렸을 때 툴팁이 커서에서 세로로 얼마나 떨어져 표시될지 픽셀 단위로 설정합니다. 아래쪽은 (-), 위쪽은 (+)입니다."
L["How far a mouseover tooltip sits from your mouse, left (-) or right (+), in pixels."] = "마우스를 올렸을 때 툴팁이 커서에서 가로로 얼마나 떨어져 표시될지 픽셀 단위로 설정합니다. 왼쪽은 (-), 오른쪽은 (+)입니다."
L["How far the camera can zoom out. It starts at Blizzard's own limit."] = "카메라를 얼마나 멀리까지 확대 축소할 수 있는지 설정합니다. 기본값은 블리자드의 제한 거리입니다."
L["How fast it comes back.\n* Fast: 0.2 seconds\n* Slow: 0.4 seconds"] = "다시 나타나는 속도를 설정합니다.\n* 빠르게: 0.2초\n* 느리게: 0.4초"
L["How fast it fades away.\n* Fast: 0.2 seconds\n* Slow: 0.4 seconds\n* Slower: fades to about half over 2 seconds, then 2 seconds later fades out"] = "사라지는 속도를 설정합니다.\n* 빠르게: 0.2초\n* 느리게: 0.4초\n* 더 느리게: 2초 동안 절반 정도로 흐려지고, 그로부터 2초 후 완전히 사라집니다."
L["How fast the camera zooms with the mouse wheel. It starts at Blizzard's own speed."] = "마우스 휠을 사용할 때 카메라가 확대 및 축소되는 속도를 설정합니다. 기본값은 블리자드의 기본 속도입니다."
L["How It Works"] = "작동 방식"
L["How long before a buff runs out it counts as missing."] = "강화 효과가 만료되기 얼마 전부터 효과가 없는 것으로 간주할지 설정합니다."
L["How long it stays after it was last needed, in seconds, before it fades."] = "마지막으로 필요했던 시점부터 페이드되기 전까지 유지되는 시간입니다. 초 단위로 설정합니다."
L["How long the buff has left, on each icon."] = "각 아이콘에 강화 효과의 남은 시간을 표시합니다."
L["How long the chat stays, in seconds, after it was last needed. Then it fades."] = "채팅이 마지막으로 필요했던 시점부터 페이드되기 전까지 유지되는 시간입니다. 초 단위로 설정합니다."
L["How long the meter stays, in seconds, after it was last needed. Then it fades."] = "측정기가 마지막으로 필요했던 시점부터 페이드되기 전까지 유지되는 시간입니다. 초 단위로 설정합니다."
L["How many bag slots you have free, at the bottom of the loot window. It turns red when your bags are full."] = "전리품 창 하단에 표시할 가방의 빈 슬롯 수입니다. 가방이 가득 차면 빨간색으로 바뀝니다."
L["How many buffs show. They take as many rows as they need."] = "표시할 강화 효과의 개수입니다. 필요한 만큼 여러 행에 걸쳐 표시됩니다."
L["How many debuffs show. They take as many rows as they need."] = "표시할 약화 효과의 개수입니다. 필요한 만큼 여러 행에 걸쳐 표시됩니다."
L["How many of them you want up:\n* Each of Them: an icon for every one you lack\n* Any One of Them: one icon, gone as soon as one is on you"] = "표시할 효과의 개수를 설정합니다.\n* 각각: 자신에게 없는 효과마다 아이콘을 하나씩 표시합니다.\n* 하나라도: 아이콘 하나만 표시하며, 효과 중 하나라도 자신에게 적용되면 사라집니다."
L["How party frames look:\n* Classic: like the player frame\n* Raid Style: compact tiles"] = "파티 프레임의 외형을 설정합니다.\n* 클래식: 플레이어 프레임과 같은 형태\n* 공격대 스타일: 간결한 타일 형태"
L["How quests are ordered:\n* By Zone: your zone first\n* By Distance: nearest first\n* By Level: lowest first\n* By Progress: furthest along first"] = "퀘스트 정렬 방식을 설정합니다.\n* 지역별: 현재 지역의 퀘스트를 먼저 표시합니다.\n* 거리별: 가까운 퀘스트부터 표시합니다.\n* 레벨별: 낮은 레벨부터 표시합니다.\n* 진행도별: 진행이 가장 많이 된 퀘스트부터 표시합니다."
L["How see-through it gets when faded. 0% is invisible."] = "페이드될 때 얼마나 투명해질지 설정합니다. 0%는 완전히 보이지 않는 상태입니다."
L["How see-through the edit box is."] = "입력 상자의 투명도를 설정합니다."
L["How Simplified Item Stats shortens lines with both healing and damage:\n* Off: the long line, unchanged\n* Spell Healing / Spell Damage: both numbers as they are\n* Spell Healing / Spell Power: the damage as Spell Power, plus the extra healing"] = "간소화된 아이템 능력치가 치유와 피해를 모두 포함하는 문장을 줄여 표시하는 방식입니다.\n* 끄기: 원래의 긴 문장을 그대로 표시합니다.\n* 주문 치유 / 주문 피해: 두 수치를 모두 원래대로 표시합니다.\n* 주문 치유 / 주문력: 피해량은 주문력으로 표시하고 추가 치유량을 함께 표시합니다."
L["How tall each plate's health bar is."] = "각 이름표 생명력 바의 높이입니다."
L["How tall the cast bar is."] = "시전 바의 높이입니다."
L["How the bar fades:\n* Show Speed: how fast it comes back\n* Hide Speed: how fast it fades away\n* Faded Opacity: how far it fades. At 0% it disappears"] = "바의 페이드 방식을 설정합니다.\n* 표시 속도: 바가 얼마나 빠르게 다시 나타나는지 설정합니다.\n* 숨김 속도: 바가 얼마나 빠르게 사라지는지 설정합니다.\n* 페이드 불투명도: 얼마나 투명해질지 설정합니다. 0%에서는 완전히 사라집니다."
L["How the box you type in looks:\n* FlareUI: Blizzard's own edit box\n* Modern: a dark box with the border of your choice"] = "텍스트를 입력하는 상자의 외형을 설정합니다.\n* FlareUI: 블리자드 기본 입력 상자\n* 모던: 원하는 테두리를 적용할 수 있는 어두운 입력 상자"
L["How the chat fades:\n* Show Speed: how fast it comes back\n* Hide Speed: how fast it fades away\n* Faded Opacity: how far it fades. At 0% it disappears"] = "채팅의 페이드 방식을 설정합니다.\n* 표시 속도: 채팅이 얼마나 빠르게 다시 나타나는지 설정합니다.\n* 숨김 속도: 채팅이 얼마나 빠르게 사라지는지 설정합니다.\n* 페이드 불투명도: 얼마나 투명해질지 설정합니다. 0%에서는 완전히 사라집니다."
L["How the chat's frame looks:\n* FlareUI: the quest tracker's FlareUI look, with Blizzard's title strip behind the tabs, a line along the bottom and the FlareUI Thick border\n* Modern: a plain frame with the border of your choice"] = "채팅 프레임의 외형을 설정합니다.\n* FlareUI: 퀘스트 추적기에 적용된 FlareUI 스타일입니다. 탭 뒤에 블리자드 제목 표시줄이 있고, 아래쪽에 선이 있으며 FlareUI 두꺼운 테두리가 적용됩니다.\n* 모던: 원하는 테두리를 적용할 수 있는 단순한 프레임입니다."
L["How the lines line up:\n* Left: icon, then the text\n* Centre: icon and text centred (at the cursor: right above it)\n* Right: the text, then the icon, lined up on the right (at the cursor: to its left)"] = "항목을 정렬하는 방식을 설정합니다.\n* 왼쪽: 아이콘 다음에 텍스트를 표시합니다.\n* 가운데: 아이콘과 텍스트를 가운데 정렬합니다. 커서 위치에서는 바로 위에 표시됩니다.\n* 오른쪽: 텍스트 다음에 아이콘을 표시하고 오른쪽으로 정렬합니다. 커서 위치에서는 왼쪽에 표시됩니다."
L["How the meter or the threat window fades:\n* Show Speed: how fast it comes back\n* Hide Speed: how fast it fades away\n* Faded Opacity: how far it fades. At 0% it disappears"] = "측정기 또는 위협 수준 창의 페이드 방식을 설정합니다.\n* 표시 속도: 얼마나 빠르게 다시 나타나는지 설정합니다.\n* 숨김 속도: 얼마나 빠르게 사라지는지 설정합니다.\n* 페이드 불투명도: 얼마나 투명해질지 설정합니다. 0%에서는 완전히 사라집니다."
L["How the meter's and the threat window's frames look:\n* FlareUI: the quest tracker's FlareUI look, with Blizzard's title strip behind the header, a line along the bottom and the FlareUI Thick border\n* Modern: a plain frame with the border of your choice"] = "측정기 및 위협 수준 창의 프레임 외형을 설정합니다.\n* FlareUI: 퀘스트 추적기에 적용된 FlareUI 스타일입니다. 머리글 뒤에 블리자드 제목 표시줄이 있고, 아래쪽에 선이 있으며 FlareUI 두꺼운 테두리가 적용됩니다.\n* 모던: 원하는 테두리를 적용할 수 있는 단순한 프레임입니다."
L["How the shown icons line up:\n* Blizzard: a fixed spot for each, with gaps\n* The others: packed together, growing that way"] = "표시되는 아이콘의 정렬 방식을 설정합니다.\n* 블리자드: 각 아이콘을 일정한 간격으로 고정된 위치에 배치합니다.\n* 그 외: 아이콘을 서로 붙여 배치하고 해당 방향으로 확장합니다."
L["How the tracker's frame looks:\n* Blizzard: like the game's own tracker, with its textured strips behind the title and the zone headings, and no background, border or scroll bar\n* FlareUI: the same strips on FlareUI's frame, with its border and a line along the bottom\n* Modern: no strips, with the background and border of your choice"] = "추적기 프레임의 외형을 설정합니다.\n* 블리자드: 게임 기본 추적기와 같은 형태입니다. 제목과 지역 제목 뒤에 무늬가 있는 띠가 표시되며, 배경과 테두리 및 스크롤 바는 없습니다.\n* FlareUI: FlareUI 프레임에 동일한 띠를 적용하고 테두리와 아래쪽 선을 표시합니다.\n* 모던: 띠 없이 원하는 배경과 테두리를 적용합니다."
L["How this frame's auras line up. Default is Blizzard's order: yours first, then the important ones."] = "이 프레임의 오라 정렬 방식을 설정합니다. 기본값은 블리자드 순서로, 자신의 효과를 먼저 표시한 다음 중요한 효과를 표시합니다."
L["How wide each plate's health bar is."] = "각 이름표 생명력 바의 너비입니다."
L["How you open the addon button drawer:\n* Off: no drawer. Addon buttons stay on the minimap\n* Sundial: click the day/night sundial\n* Blizzard: click the small addon button under the calendar. Its number is how many addons are in the drawer"] = "애드온 버튼 서랍을 여는 방식을 설정합니다.\n* 끄기: 서랍을 사용하지 않습니다. 애드온 버튼은 미니맵에 그대로 표시됩니다.\n* 해시계: 낮/밤 해시계를 클릭하여 엽니다.\n* 블리자드: 달력 아래에 있는 작은 애드온 버튼을 클릭하여 엽니다. 버튼의 숫자는 서랍에 들어 있는 애드온의 개수입니다."
L["How your bags show your items:\n* Category Filters: buttons for Quest Items, Equipment, Materials and Consumables. Pick one and everything else dims\n* Category Rows: the combined backpack in sections: Quest Items, Equipment, Materials, Consumables, Junk and Other\n* Category Rows + Sets: a section for each of your equipment sets too, after Equipment"] = "가방에서 아이템을 표시하는 방식을 설정합니다.\n* 범주 필터: 퀘스트 아이템, 장비, 재료 및 소모품 버튼을 표시합니다. 하나를 선택하면 나머지 아이템은 흐리게 표시됩니다.\n* 범주 행: 통합 가방을 퀘스트 아이템, 장비, 재료, 소모품, 잡동사니 및 기타 항목으로 나눕니다.\n* 범주 행 + 세트: 장비 다음에 각 장비 세트별 항목도 별도의 범주로 표시합니다."
L["How your buffs and debuffs line up."] = "강화 효과와 약화 효과의 정렬 방식을 설정합니다."
L["Icon Alerts"] = "아이콘 알림"
L["Icon Shape"] = "아이콘 모양"
L["Icon Size"] = "아이콘 크기"
L["Icon size, icons per row and placement are set in Edit Mode."] = "아이콘 크기, 행당 아이콘 수 및 배치 위치는 편집 모드에서 지정합니다."
L["Icons"] = "아이콘"
L["Icons in chat:\n* Item and Spell Icons: the item's or spell's icon inside its link\n* Race Icons: the sender's race icon before their name\n* Class Icons: the sender's class icon before their name"] = "채팅에 표시되는 아이콘입니다.\n* 아이템 및 주문 아이콘: 아이템이나 주문 링크 안에 해당 아이콘을 표시합니다.\n* 종족 아이콘: 보낸 사람의 이름 앞에 종족 아이콘을 표시합니다.\n* 직업 아이콘: 보낸 사람의 이름 앞에 직업 아이콘을 표시합니다."
L["Icons per Row"] = "행당 아이콘 수"
L["Ignore Chat Fade"] = "채팅 페이드 무시"
L["Import"] = "가져오기"
L["Import Profile"] = "프로필 가져오기"
L["Import shows the string's version, UI scale and any fonts or textures you're missing, then reloads. To share Edit Mode layouts, use Edit Mode."] = "가져오기를 하면 문자열 버전, UI 크기 비율 및 누락된 글꼴이나 텍스처를 표시한 다음 인터페이스를 다시 불러옵니다. 편집 모드 레이아웃을 공유하려면 편집 모드를 사용하세요."
L["Important Cast Glow"] = "중요한 시전 빛 효과"
L["Imported"] = "가져옴"
L["In a Capital City"] = "대도시에 있을 때"
L["In a fight, it waits until the fight ends."] = "전투 중에는 전투가 끝날 때까지 기다립니다."
L["In a fight, the border and portrait pulse red. With aggro, the threat colour shows instead."] = "전투 중에는 테두리와 초상화가 빨간색으로 점멸합니다. 어그로가 발생하면 대신 위협 수준 색상이 표시됩니다."
L["In a Group"] = "그룹 내"
L["In a Party"] = "파티 내"
L["In a Raid"] = "공격대 내"
L["In an Instance"] = "인스턴스 내"
L["In caster form, Power shows your mana. For a mana bar on your player frame, tick Mana on Shapeshift in its Edit Mode settings."] = "시전자 형태에서는 자원에 마나가 표시됩니다. 플레이어 프레임에 마나 바를 표시하려면 편집 모드 설정에서 변신 중 마나를 선택하세요."
L["In Combat"] = "전투 중"
L["In Combat keeps your own setting and gives it back when you pick another choice."] = "전투 중에는 현재 설정을 유지하며, 다른 선택 항목을 지정하면 해당 설정으로 돌아갑니다."
L["In combat, buff procs need the buff in the Cooldown Manager's Tracked Buffs, unless the game shows its own proc alert."] = "전투 중 강화 효과 발동 알림을 표시하려면 해당 강화 효과가 재사용 대기시간 관리자의 추적 중인 강화 효과에 등록되어 있어야 합니다. 단, 게임 자체 발동 알림이 표시되는 효과는 예외입니다."
L["In Dungeons"] = "던전 내"
L["In Dungeons and Raids"] = "던전 및 공격대 내"
L["In Gamepad mode the controller's buttons belong to its action bar."] = "게임패드 모드에서는 컨트롤러 버튼이 해당 행동 단축바에 할당됩니다."
L["In Gamepad mode, Blizzard's tracker replaces FlareUI's, so D-pad Up, quest items and menus work with the controller."] = "게임패드 모드에서는 FlareUI 추적기 대신 블리자드 추적기가 사용되므로 방향 패드 위쪽 버튼으로 퀘스트 아이템과 메뉴를 조작할 수 있습니다."
L["In Gamepad mode, open Edit Mode from the game menu."] = "게임패드 모드에서는 게임 메뉴에서 편집 모드를 여세요."
L["In Instances"] = "인스턴스 내"
L["In Raids"] = "공격대 내"
