L["New quests are accepted when you talk to the NPC. Grey, repeatable and daily quests wait for you."] = "NPC와 대화하면 새 퀘스트를 자동으로 수락합니다. 회색 퀘스트, 반복 퀘스트 및 일일 퀘스트는 자동 수락하지 않습니다."
