L["No \"will bind to you\" question when you:\n* Loot an item\n* Roll Need or Greed"] = "다음 상황에서 \"획득 시 귀속됩니다\"라는 확인 창을 표시하지 않습니다.\n* 아이템 획득\n* 차비 또는 입찰 주사위 굴림"
L["No addon buttons"] = "애드온 버튼 없음"
