L["No frame round the micro menu. Blizzard's frame only fits the menu in its default place."] = "마이크로 메뉴 주위에 프레임을 표시하지 않습니다. 블리자드 프레임은 메뉴가 기본 위치에 있을 때만 크기가 맞습니다."
L["No helpful spells to cast on others yet."] = "아직 다른 대상에게 시전할 수 있는 유용한 주문이 없습니다."
L["No hostile target"] = "적대적 대상 없음"
L["No keys yet."] = "아직 키가 없습니다."
L["No macros yet: make one with /macro and it appears here."] = "아직 매크로가 없습니다. /macro로 매크로를 만들면 여기에 표시됩니다."
L["No mounts or toys yet."] = "아직 탈것이나 장난감이 없습니다."
