L["None"] = "없음"
L["None in your bags."] = "가방에 없습니다."
L["Not available on this character."] = "이 캐릭터에서는 사용할 수 없습니다."
L["Not bound"] = "귀속되지 않음"
L["Not enough gold to repair (%s)."] = "수리할 골드가 부족합니다. (%s)"
L["Not holding it: 100% is where you pull it. Holding it: your threat against the next in line, so 200% is twice theirs, and near 100% you're about to lose it."] = "몬스터를 담당하지 않을 때는 100%가 어그로를 가져오는 기준입니다. 담당 중일 때는 다음 순위 대상과 비교한 자신의 위협 수준을 나타냅니다. 따라서 200%는 상대의 두 배이며, 100%에 가까워지면 어그로를 잃을 위험이 있습니다."
L["Not in a Capital City"] = "대도시에 있지 않음"
L["Not in combat, and not at a vendor, mailbox, bank, auction house or in a trade."] = "전투 중이 아니며, 상인, 우편함, 은행, 경매장 또는 거래 중이 아닐 때."
L["Not in combat, and not at a vendor, mailbox, bank, auction house or in a trade. A box that won't open is left alone."] = "전투 중이 아니며, 상인, 우편함, 은행, 경매장 또는 거래 중이 아닐 때. 열리지 않는 상자는 건드리지 않습니다."
L["not in your bags"] = "가방에 없음"
L["Not Mounted"] = "탈것에 탑승하지 않음"
L["Not Now"] = "지금은 안 함"
