L["Not with Category Rows, whose headers sit above their sections."] = "범주 행에서는 사용할 수 없습니다. 범주 행의 머리글은 각 영역 위에 표시됩니다."
L["Nothing here yet: learn a profession and its spells appear here."] = "아직 아무것도 없습니다. 전문 기술을 배우면 해당 기술이 여기에 표시됩니다."
L["Nothing here yet."] = "아직 아무것도 없습니다."
