L["Notifications"] = "알림"
L["NPC Names"] = "NPC 이름"
L["NPC speech starts with an orange [Name] instead of \"Name says:\"."] = "NPC의 대화가 \"이름이 말합니다:\" 대신 주황색 [이름]으로 시작합니다."
