L["On"] = "켜기"
L["On a 4K screen, choose 1080p: everything is a normal size and stays just as sharp. Too small to click? Type /fui scale reset in chat."] = "4K 화면에서는 1080p를 선택하세요. 모든 요소가 일반적인 크기로 표시되면서 선명도도 그대로 유지됩니다. 클릭하기에 너무 작다면 채팅창에 /fui scale reset을 입력하세요."
L["On a ready check, every reminder glows for a few seconds and the sound plays."] = "전투 준비 확인이 시작되면 모든 알림이 몇 초 동안 빛나고 소리가 재생됩니다."
L["On Cooldown"] = "재사용 대기시간 중"
L["On Flight Paths"] = "비행 경로 이용 중"
L["On for NPCs at first, off for players and Minor."] = "기본적으로 NPC에게는 켜지고, 플레이어와 하급 적에게는 꺼집니다."
L["On Low Health"] = "생명력이 낮을 때"
