L["One Line"] = "한 줄"
L["One outline for every FlareUI font, over its own Outline choice. Each Font's Own leaves them as they are."] = "각 글꼴의 개별 윤곽선 설정 대신 모든 FlareUI 글꼴에 하나의 윤곽선을 적용합니다. 각 글꼴 자체 설정을 선택하면 기존 설정을 유지합니다."
L["One reload and your choices take effect."] = "한 번 다시 불러오면 선택한 설정이 적용됩니다."
L["Only %s"] = "%s만"
