L["Only Dispellable"] = "해제 가능한 항목만"
L["Only Dispellable Debuffs"] = "해제 가능한 약화 효과만"
L["Only for spells on your action bars."] = "행동 단축바에 있는 주문에만 적용됩니다."
L["Only for tooltips in the HUD Tooltip box. Tooltips at your mouse use Offset X and Offset Y instead."] = "HUD 툴팁 상자에 표시되는 툴팁에만 적용됩니다. 마우스 커서에 표시되는 툴팁에는 대신 X 오프셋과 Y 오프셋이 적용됩니다."
L["Only Important"] = "중요 항목만"
L["Only Mana Power Bars"] = "마나 자원 막대만"
