L["Only Party"] = "파티만"
L["Only Provider"] = "제공자만"
L["Only Purgeable"] = "제거 가능한 항목만"
L["Only Tanks"] = "탱커만"
L["Only the buffs you cast (your heals over time, your blessings). Off: everyone's buffs."] = "자신이 시전한 강화 효과만 표시합니다. (지속 치유 효과, 축복 등) 끄면 모든 플레이어의 강화 효과를 표시합니다."
L["Only the buffs you cast on yourself."] = "자신에게 시전한 강화 효과만 표시합니다."
L["Only the debuffs you can dispel, plus boss debuffs and other important ones, as on Blizzard's raid frames."] = "블리자드 공격대 프레임처럼 자신이 해제할 수 있는 약화 효과와 우두머리의 약화 효과 및 기타 중요한 효과만 표시합니다."
L["Only the frame style in use changes."] = "현재 사용 중인 프레임 스타일만 변경됩니다."
L["Only This Character"] = "이 캐릭터만"
L["Only When in Use"] = "사용 중일 때만"
L["Only When In Use: the bar appears when this weapon swings and leaves soon after the swings stop."] = "사용 중일 때만: 이 무기가 공격할 때 막대가 나타나며, 공격이 멈추면 곧 사라집니다."
