L["Open When Clicked"] = "클릭 시 열기"
L["Open with Character Window"] = "캐릭터 창과 함께 열기"
L["Open world only: inside dungeons the game hides quest progress. Questie's own nameplate icons win when they're on."] = "오픈 월드에서만 표시됩니다. 던전 안에서는 게임이 퀘스트 진행 상황을 숨깁니다. Questie의 자체 이름표 아이콘이 활성화되어 있으면 해당 아이콘이 우선합니다."
L["Open your quest log to read this quest."] = "이 퀘스트를 읽으려면 퀘스트 목록을 여세요."
L["Opening"] = "여는 중"
L["Opening a radial with its key targets the unit under your mouse first:\n* Always: every time\n* Shift, Ctrl or Alt: only with that key held. Alt+3 targets and opens, plain 3 only opens"] = "단축키로 방사형 메뉴를 열면 먼저 마우스 아래에 있는 유닛을 대상으로 지정합니다.\n* 항상: 매번 대상 지정\n* Shift, Ctrl 또는 Alt: 해당 키를 누르고 있을 때만 대상 지정. Alt+3은 대상을 지정하고 메뉴를 열며, 3만 누르면 메뉴만 엽니다."
L["Opens Blizzard's window where you pick what each bar tracks."] = "각 막대가 추적할 항목을 선택하는 블리자드 창을 엽니다."
