L["Options for the whole interface: your characters, windows, scale and language."] = "전체 인터페이스 설정입니다. 캐릭터, 창, 크기 및 언어를 설정합니다."
L["Or open it with a press instead of a hold"] = "또는 길게 누르는 대신 한 번 눌러 열 수 있습니다."
