L["Placed and scaled in Edit Mode as \"FlareUI Loot Window\". With Blizzard's Loot Under Mouse on, it opens at your cursor."] = "편집 모드에서 \"FlareUI Loot Window\"로 위치와 크기를 설정합니다. 블리자드의 마우스 아래 전리품 창 기능이 켜져 있으면 커서 위치에 열립니다."
