L["Plates of units just off the screen stay at its edge."] = "화면에서 조금 벗어난 유닛의 이름표를 화면 가장자리에 유지합니다."
L["Plates of units out of your spells' range fade to this opacity."] = "주문 사거리 밖에 있는 유닛의 이름표를 이 투명도로 흐리게 표시합니다."
L["Plates stay up out of combat too."] = "전투 중이 아닐 때도 이름표를 계속 표시합니다."
