L["Player Cast Bar"] = "플레이어 시전 바"
L["Player Frame"] = "플레이어 프레임"
L["Player Names"] = "플레이어 이름"
L["Player names in their class colour, without the realm. Say lines start with a clickable [Say] that switches your chat to Say."] = "플레이어 이름을 서버 이름 없이 직업 색상으로 표시합니다. 일반 대화 메시지는 클릭 가능한 [일반]으로 시작하며, 클릭하면 채팅 모드가 일반 대화로 전환됩니다."
L["Player names in their class colour."] = "플레이어 이름을 직업 색상으로 표시합니다."
L["Player, target, focus, pet and party frames in FlareUI's style."] = "플레이어, 대상, 주시 대상, 소환수 및 파티 프레임을 FlareUI 스타일로 표시합니다."
L["Players"] = "플레이어"
L["Players and NPCs only hide FlareUI's own plates. An Enemy Player or Enemy NPC set to Blizzard's plates always shows."] = "플레이어와 NPC 설정은 FlareUI 자체 이름표만 숨깁니다. 블리자드 이름표로 설정된 적 플레이어 또는 적 NPC 이름표는 항상 표시됩니다."
L["Players' health bars in their class colour. Off: green. NPCs keep their reaction colour."] = "플레이어의 생명력 바를 직업 색상으로 표시합니다. 끄면 녹색으로 표시됩니다. NPC는 기존 반응 색상을 유지합니다."
L["Players' names on full plates in their class colour. Name Only plates always colour them."] = "전체 이름표에 표시되는 플레이어 이름을 직업 색상으로 표시합니다. 이름만 표시하는 이름표에서는 항상 직업 색상이 적용됩니다."
L["Playstyle"] = "플레이 스타일"
L["Point at a zone on a continent map to see its level range under its name, coloured for your level."] = "대륙 지도에서 지역에 마우스를 올리면 이름 아래에 해당 지역의 레벨 범위가 자신의 레벨에 맞는 색상으로 표시됩니다."
L["Point at the XP bar for its details: XP to the next level, rested XP, quest XP and XP per hour. Reputation and honor show theirs."] = "경험치 바에 마우스를 올리면 다음 레벨까지 필요한 경험치, 휴식 경험치, 퀘스트 경험치 및 시간당 경험치를 확인할 수 있습니다. 평판과 명예도 각각의 정보를 표시합니다."
L["Poisons, sharpening stones, oils and shaman weapon spells, at the start of the buffs. They follow Hide Buffs too."] = "독, 숫돌, 기름 및 주술사의 무기 강화 주문을 강화 효과 목록의 맨 앞에 표시합니다. 강화 효과 숨기기 설정도 동일하게 적용됩니다."
