L["Press |cffffd100Esc|r, then choose |cffffd100Edit Mode|r. Click anything on your screen to move it and change its size and look."] = "|cffffd100Esc|r를 누른 다음 |cffffd100편집 모드|r를 선택하세요. 화면의 항목을 클릭하면 위치와 크기 및 모양을 변경할 수 있습니다."
