L["that radial is full (%d buttons)."] = "해당 방사형 메뉴가 가득 찼습니다(버튼 %d개)."
L["That's an Edit Mode layout code. Import it in Esc > Edit Mode > Layout > Import."] = "편집 모드 배치 코드입니다. Esc > 편집 모드 > 배치 > 가져오기에서 가져오세요."
L["The \"PvP\" line on players and creatures flagged for PvP, like enemy city guards."] = "PvP 상태로 표시된 플레이어와 생명체(적 도시 경비병 등)의 \"PvP\" 항목입니다."
L["The Alliance or Horde line on tooltips."] = "툴팁에 얼라이언스 또는 호드 항목을 표시합니다."
L["The art at each end of the main action bar:\n* Shown: as the game draws them\n* Behind Bars: under your action buttons, not over them\n* Hidden: gone"] = "기본 행동 단축바 양쪽 끝의 장식입니다.\n* 표시: 게임의 기본 방식으로 표시합니다.\n* 단축바 뒤: 행동 버튼 위가 아닌 아래에 표시합니다.\n* 숨김: 표시하지 않습니다."
L["The backpack starts at the top left and fills left to right, downwards. Combine Empty Slots' slot comes last, at the bottom."] = "배낭은 왼쪽 위에서 시작해 왼쪽에서 오른쪽으로, 위에서 아래로 채워집니다. 빈 슬롯 통합 기능의 슬롯은 맨 아래 마지막에 배치됩니다."
L["The bag bar without its frame, and an arrow beside the backpack that hides and shows the other bag slots. They open on their own while you hold an item on the cursor, so you can drop it in a bag."] = "프레임 없이 표시되는 가방 바와 다른 가방 슬롯을 숨기거나 표시하는 배낭 옆 화살표입니다. 커서에 아이템을 들고 있으면 가방이 자동으로 열려 아이템을 넣을 수 있습니다."
L["The bank and guild bank always open your bags."] = "은행과 길드 은행을 열면 항상 가방도 함께 열립니다."
L["The bank never gets narrower than Blizzard's. With fewer columns, the slots sit in the middle."] = "은행 창의 너비는 블리자드 기본 너비보다 좁아지지 않습니다. 열 수가 적으면 슬롯이 가운데에 배치됩니다."
L["The bar stays up in caster form too, not only in Bear and Cat Form."] = "곰 변신과 표범 변신뿐 아니라 시전자 변신 상태에서도 막대를 표시합니다."
L["The bar turns red while your target is out of reach of this attack."] = "대상이 이 공격의 사거리 밖에 있으면 막대가 빨간색으로 바뀝니다."
L["The bar's size."] = "막대의 크기입니다."
L["The bars fill from the other side, and the texts swap sides, so the frame faces the player frame."] = "막대가 반대쪽에서부터 채워지고 텍스트도 서로 위치를 바꿔 플레이어 프레임을 향하도록 합니다."
L["The Blizzard frame style always uses Blizzard's colours. Difficulty, complete and focus colours keep their meaning in both."] = "블리자드 프레임 스타일은 항상 블리자드 색상을 사용합니다. 난이도, 완료 및 주시 색상은 두 스타일 모두에서 동일한 의미를 유지합니다."
L["The border around the chat. None hides it."] = "채팅창 테두리입니다. 없음으로 설정하면 테두리를 숨깁니다."
L["The border around the meter. None hides it."] = "측정기 테두리입니다. 없음으로 설정하면 테두리를 숨깁니다."
L["The border around the Modern edit box. None leaves the dark box without an edge."] = "모던 편집 상자의 테두리입니다. 없음으로 설정하면 어두운 상자에 테두리를 표시하지 않습니다."
L["The border around the tracker. None hides it."] = "추적기 테두리입니다. 없음으로 설정하면 테두리를 숨깁니다."
L["The border pulses in the threat colour while the unit has aggro."] = "유닛이 어그로를 보유하는 동안 테두리가 위협 수준 색상으로 점멸합니다."
L["The border pulses in the threat colour while this member has aggro."] = "해당 파티원이 어그로를 보유하는 동안 테두리가 위협 수준 색상으로 점멸합니다."
L["The border pulses in the threat colour while you have threat on it."] = "해당 유닛에 대한 위협 수준이 있을 때 테두리가 위협 수준 색상으로 점멸합니다."
L["The border round each plate's bar. The cast bar keeps FlareUI Thin when you pick FlareUI Thick."] = "각 이름표 막대의 테두리입니다. FlareUI Thick을 선택해도 시전 바는 FlareUI Thin을 유지합니다."
L["The bronze ring beside FlareUI's bars."] = "FlareUI 막대 옆의 청동색 고리입니다."
L["The Buffs & Debuffs frames show every aura already, so Show leaves them off its list."] = "강화 효과 및 약화 효과 프레임에 모든 오라가 이미 표시되므로 표시 목록에서는 제외합니다."
L["The buffs and debuffs on you right now. Pick one to add it."] = "현재 자신에게 적용된 강화 효과와 약화 효과입니다. 하나를 선택해 추가하세요."
L["The button you used last is lit when the radial opens. Press the radial's button again to use it."] = "방사형 메뉴를 열면 마지막으로 사용한 버튼이 강조 표시됩니다. 해당 버튼을 다시 누르면 실행됩니다."
L["The buttons and bars you look at all day."] = "항상 보게 되는 버튼과 막대입니다."
L["The cast bar's border, apart from the plate's."] = "이름표 테두리와 별개로 설정하는 시전 바의 테두리입니다."
L["The cast bar's border. Frame Border matches the frame's own border."] = "시전 바의 테두리입니다. 프레임 테두리를 선택하면 프레임 자체의 테두리와 일치합니다."
L["The cast bar's texture, apart from the health bar's."] = "생명력 바와 별개로 설정하는 시전 바의 질감입니다."
L["The chat window stays up while the Meter tab is open."] = "측정기 탭이 열려 있는 동안 채팅창을 계속 표시합니다."
L["The chat's frame, tabs and buttons fade as set, but the messages stay. Works with any Visibility."] = "설정에 따라 채팅창 프레임, 탭 및 버튼은 흐려지지만 메시지는 그대로 유지됩니다. 모든 표시 방식에서 작동합니다."
L["The chat's visibility and fading are set in Edit Mode."] = "채팅창의 표시 여부와 페이드 효과는 편집 모드에서 설정합니다."
L["The colour of the Tracked Bars."] = "추적 막대의 색상입니다."
L["The colours Status Colouring paints, next to sample buttons:\n* Out of Range\n* Out of Mana\n* Unusable\n* On Cooldown (not the global cooldown)\nPalettes: FlareUI (default), Blizzard, or Disabled to leave the buttons as the game colours them. Change any colour and it becomes Custom."] = "상태별 색상 지정이 적용하는 색상입니다. 예시 버튼 옆에 표시됩니다.\n* 사거리 밖\n* 마나 부족\n* 사용 불가\n* 재사용 대기시간 중(전역 재사용 대기시간 제외)\n색상 팔레트: FlareUI(기본값), 블리자드 또는 비활성화. 비활성화하면 게임에서 지정한 버튼 색상을 그대로 사용합니다. 색상을 하나라도 변경하면 사용자 지정으로 전환됩니다."
L["The coordinates and other small text on the map."] = "지도에 표시되는 좌표 및 기타 작은 텍스트입니다."
L["The countdown on the icons."] = "아이콘에 표시되는 카운트다운입니다."
L["The damage and healing numbers over what you hit. Default keeps Blizzard's font."] = "공격한 대상 위에 표시되는 피해량 및 치유량 숫자입니다. 기본값은 블리자드 글꼴을 사용합니다."
L["The damage and heals on the portrait (Show Combat Text). Auto sizes it to the portrait. Crits show 50% bigger."] = "초상화에 표시되는 피해량과 치유량입니다(전투 메시지 표시). 초상화 크기에 맞춰 자동으로 조정되며, 치명타는 50% 더 크게 표시됩니다."
L["The dark sweep on your totems as their time runs out:\n* Over the Icon: across the icon\n* Around the Border: round the ring\n* Both: one disc over icon and ring"] = "토템의 지속 시간이 끝나갈 때 표시되는 어두운 진행 효과입니다.\n* 아이콘 위: 아이콘 전체에 표시합니다.\n* 테두리 둘레: 고리 형태로 표시합니다.\n* 둘 다: 아이콘과 고리 위에 하나의 원형 효과를 표시합니다."
L["The drawer opens while you point at the day/night badge and closes when you move away. Clicking still works."] = "낮/밤 표시 아이콘에 마우스를 올리면 서랍이 열리고 마우스를 옮기면 닫힙니다. 클릭 기능도 그대로 작동합니다."
L["The edge that stays put as the tracker grows:\n* Automatic: whichever edge is nearer the edge of the screen\n* Top: grows downward\n* Bottom: grows upward"] = "추적기가 확장될 때 고정되는 가장자리입니다.\n* 자동: 화면 가장자리에 더 가까운 쪽을 고정합니다.\n* 위쪽: 아래 방향으로 확장됩니다.\n* 아래쪽: 위 방향으로 확장됩니다."
L["The elixirs, Zanza, juju and Blasted Lands buffs you want kept up. Click an icon to use one from your bags."] = "유지하고 싶은 영약, 잔자, 주주 및 저주받은 땅 강화 효과입니다. 아이콘을 클릭하면 가방에 있는 아이템을 사용합니다."
L["The encounter's bosses, mirrored like the target frame."] = "대상 프레임처럼 좌우가 반전된 형태로 표시되는 우두머리 프레임입니다."
L["The fight's running time in the meter's title."] = "측정기 제목에 표시되는 전투 경과 시간입니다."
L["The fill of the FlareUI XP Bar."] = "FlareUI 경험치 바의 채우기 색상입니다."
L["The first line: a name or an item."] = "첫 번째 줄에 이름이나 아이템을 표시합니다."
L["The flag carriers in battlegrounds, in your frame style: their name, health, power, class and faction. Click one to target it, right-click to make it your focus."] = "전장 깃발 운반자를 현재 프레임 스타일로 표시합니다. 이름, 생명력, 자원, 직업 및 진영이 표시됩니다. 클릭하면 대상으로 지정하고, 오른쪽 클릭하면 주시 대상으로 지정합니다."
L["The FlareUI Layout"] = "FlareUI 배치"
L["The font for all FlareUI text set to Global. Pick Global in any Fonts tab to make that text use it."] = "전역으로 설정된 모든 FlareUI 텍스트에 사용할 글꼴입니다. 글꼴 탭에서 전역을 선택하면 해당 텍스트에 이 글꼴이 적용됩니다."
L["The frame around the square minimap:\n* Bronze (Clean): Forever's heavy bronze, with the buttons and zone name on the map\n* Bronze (Header): Blizzard's metal frame, with the buttons and zone name in its title bar\n* FlareUI Thick and FlareUI Thin: FlareUI's borders, with the buttons and zone name on the map"] = "정사각형 미니맵 주변의 프레임입니다.\n* 청동색(깔끔): Forever의 두꺼운 청동색 프레임이며, 버튼과 지역 이름이 지도 위에 표시됩니다.\n* 청동색(제목 표시줄): 블리자드의 금속 프레임이며, 버튼과 지역 이름이 제목 표시줄에 표시됩니다.\n* FlareUI Thick 및 FlareUI Thin: FlareUI 테두리를 사용하며, 버튼과 지역 이름이 지도 위에 표시됩니다."
L["The frame fades while the unit is out of range."] = "유닛이 사거리 밖에 있으면 프레임이 흐려집니다."
L["The frame round the FlareUI XP Bar."] = "FlareUI 경험치 바 주변의 프레임입니다."
L["The frame whose fonts show below."] = "아래에 글꼴이 표시되는 프레임입니다."
L["The frame's size."] = "프레임의 크기입니다."
L["The game keeps that button for itself. Pick another."] = "해당 버튼은 게임에서 사용 중입니다. 다른 버튼을 선택하세요."
L["The game only lets addons delete items when you click, so it never happens on its own. The chat tells you what was deleted."] = "게임에서는 클릭할 때만 애드온이 아이템을 삭제할 수 있으므로 자동으로 삭제되는 일은 없습니다. 삭제된 아이템은 채팅창에 표시됩니다."
L["The game's own target zoom stays off while FlareUI draws the plates, so this is the only plate scaling."] = "FlareUI가 이름표를 표시하는 동안 게임 자체의 대상 확대 기능은 꺼져 있으므로, 이름표 크기는 이 설정으로만 조정됩니다."
L["The gamepad bar can't change in combat."] = "전투 중에는 게임패드 바를 변경할 수 없습니다."
L["The gamepad bar is only there in Gamepad mode."] = "게임패드 바는 게임패드 모드에서만 표시됩니다."
L["The gap between the bars. 0 makes them touch."] = "막대 사이의 간격입니다. 0으로 설정하면 서로 맞닿습니다."
L["The gap between the boss frames."] = "우두머리 프레임 사이의 간격입니다."
L["The gap between the frames. In Raid Style it's between the bars: 0 makes them touch. Each style keeps its own."] = "프레임 사이의 간격입니다. 공격대 스타일에서는 막대 사이의 간격을 조정하며, 0으로 설정하면 서로 맞닿습니다. 각 스타일은 별도의 설정을 유지합니다."
L["The gap between the groups, measured between the bars."] = "그룹 사이의 간격입니다. 막대 사이의 거리를 기준으로 측정합니다."
L["The gap between the two frames."] = "두 프레임 사이의 간격입니다."
L["The gold, silver and copper at the bottom of your bags. Default keeps Blizzard's font."] = "가방 아래쪽에 표시되는 금화, 은화 및 동화입니다. 기본값은 블리자드 글꼴을 사용합니다."
L["The guild line on players' tooltips."] = "플레이어 툴팁에 길드 정보를 표시합니다."
L["The health and cast bars' texture."] = "생명력 바와 시전 바의 질감입니다."
L["The health and power numbers show only while you point at the frame, as Blizzard's own option does."] = "블리자드 기본 옵션처럼 프레임에 마우스를 올렸을 때만 생명력과 자원 수치를 표시합니다."
L["The health bar's colour follows the health left:\n* On Low Health: red under 30%\n* By Health: green at full, yellow at half, red when nearly dead. Takes over from Class Colours.\nOffline and tapped units stay grey."] = "생명력 바의 색상을 남은 생명력에 따라 변경합니다.\n* 생명력 낮음: 생명력이 30% 미만이면 빨간색으로 표시합니다.\n* 생명력에 따라: 생명력이 가득 차면 초록색, 절반이면 노란색, 거의 고갈되면 빨간색으로 표시합니다. 직업 색상보다 우선 적용됩니다.\n오프라인 및 선점된 유닛은 회색으로 유지됩니다."
L["The Info Bar shows only while you point at the minimap."] = "미니맵에 마우스를 올렸을 때만 정보 바를 표시합니다."
L["The Info Bar sits under the minimap instead of over its bottom edge."] = "정보 바를 미니맵 아래에 배치하며, 미니맵 하단 위에는 표시하지 않습니다."
L["The item level numbers on your bag items and the character sheet. Default keeps Blizzard's font."] = "가방 아이템과 캐릭터 정보창에 표시되는 아이템 레벨 숫자입니다. 기본값은 블리자드 글꼴을 사용합니다."
L["The key for each button, on the button, in short:\n* SM4: Shift + Mouse Button 4\n* SP: Spacebar\n* WU: Mouse Wheel Up"] = "각 버튼에 표시되는 단축키를 짧게 나타냅니다.\n* SM4: Shift + 마우스 버튼 4\n* SP: 스페이스바\n* WU: 마우스 휠 위로"
L["The key on each button."] = "각 버튼에 표시되는 단축키입니다."
L["The key you pick can't be part of a radial key. Radial keys that use it stop working until you change this. Controllers and radial macros never target."] = "선택한 키는 방사형 메뉴 키의 일부로 사용할 수 없습니다. 해당 키를 사용하는 방사형 메뉴 키는 이 설정을 변경할 때까지 작동하지 않습니다. 컨트롤러와 방사형 매크로는 대상을 지정하지 않습니다."
L["The keys on the icons."] = "아이콘에 표시되는 단축키입니다."
L["The level beside the bar."] = "막대 옆에 표시되는 레벨입니다."
L["The Lich King's Missing Left Boot"] = "리치 왕의 잃어버린 왼쪽 장화"
L["The lines that float up as you loot."] = "전리품을 획득할 때 위로 떠오르는 메시지입니다."
L["The lines under each quest."] = "각 퀘스트 아래에 표시되는 줄입니다."
L["The look of the player, target, focus, party and boss frames:\n* FlareUI: the bronze ring beside FlareUI's bars\n* Forever: Blizzard's bronze frame and portrait ring\n* Modern: plain frames, the most options"] = "플레이어, 대상, 주시 대상, 파티 및 우두머리 프레임의 모양입니다.\n* FlareUI: FlareUI 막대 옆의 청동색 고리\n* Forever: 블리자드의 청동색 프레임과 초상화 고리\n* Modern: 깔끔한 프레임으로, 가장 다양한 옵션을 제공합니다."
L["The meter is in the chat's Meter tab: it fades with the chat."] = "측정기는 채팅창의 측정기 탭에 표시되며 채팅창과 함께 흐려집니다."
L["The meter takes the chat's width and height. Off: it goes back to its Edit Mode size."] = "측정기가 채팅창의 너비와 높이를 사용합니다. 끄면 편집 모드에서 설정한 크기로 돌아갑니다."
L["The meter's visibility and fading are set in Edit Mode."] = "측정기의 표시 여부와 페이드 효과는 편집 모드에서 설정합니다."
L["The minimap's shape. Changing to or from Round reloads the interface.\n* Square: FlareUI's square minimap. Pick its frame under Border\n* Round: Forever's own round minimap"] = "미니맵의 모양입니다. 원형으로 변경하거나 원형에서 다른 모양으로 변경하면 UI를 다시 불러옵니다.\n* 정사각형: FlareUI의 정사각형 미니맵입니다. 테두리에서 프레임을 선택하세요.\n* 원형: Forever의 기본 원형 미니맵입니다."
L["The most buff icons a plate shows, in two lines at most."] = "이름표에 표시할 최대 강화 효과 아이콘 수입니다. 최대 두 줄까지 표시됩니다."
L["The most debuff icons a plate shows, in two lines at most."] = "이름표에 표시할 최대 약화 효과 아이콘 수입니다. 최대 두 줄까지 표시됩니다."
L["The mouse wheel still scrolls the Blizzard style. Background Opacity shows with FlareUI and Modern, Border with Modern."] = "블리자드 스타일에서는 마우스 휠로 계속 스크롤할 수 있습니다. 배경 투명도는 FlareUI 및 Modern 스타일에서, 테두리는 Modern 스타일에서 표시됩니다."
L["The mouse wheel still scrolls the list."] = "마우스 휠로 계속 목록을 스크롤할 수 있습니다."
L["The name above the frame, on its left, centre or right. Auras above the frame move up to make room."] = "프레임 위쪽의 왼쪽, 가운데 또는 오른쪽에 표시되는 이름입니다. 공간을 확보하기 위해 프레임 위의 오라는 위쪽으로 이동합니다."
L["The name above the plate, on its left, centre or right. Buffs and debuffs above the plate move up to make room."] = "이름표 위쪽의 왼쪽, 가운데 또는 오른쪽에 표시되는 이름입니다. 공간을 확보하기 위해 이름표 위의 강화 효과와 약화 효과는 위쪽으로 이동합니다."
L["The name on Name Only plates, and the title under it."] = "이름만 표시하는 이름표에 표시되는 이름과 그 아래의 칭호입니다."
L["The Name Only preset turns this on."] = "이름만 표시 사전 설정을 선택하면 이 기능이 활성화됩니다."
L["The names on Blizzard's nameplates and over characters in the world. Default keeps their font (or the Global Font, with Game Text on)."] = "블리자드 이름표와 게임 세계의 캐릭터 위에 표시되는 이름입니다. 기본값은 기존 글꼴을 사용하며, 게임 텍스트를 켜면 전역 글꼴을 사용합니다."
L["The names on the buttons."] = "버튼에 표시되는 이름입니다."
L["The names on the radial's buttons:\n* Mouseover: the button you point at\n* Always: every button. Long names end in \"...\""] = "방사형 메뉴 버튼에 표시되는 이름입니다.\n* 마우스 오버: 마우스를 올린 버튼에만 표시합니다.\n* 항상: 모든 버튼에 표시합니다. 이름이 길면 \"...\"로 줄여 표시합니다."
L["The names over characters change after a full restart of the game, not a /reload."] = "캐릭터 위에 표시되는 이름은 /reload가 아닌 게임을 완전히 재시작한 후 변경됩니다."
L["The notes stay here, under What's New."] = "메모는 새 소식 아래에 계속 표시됩니다."
L["The number of free bag slots on the backpack button. Default keeps Blizzard's font."] = "배낭 버튼에 표시되는 가방의 빈 슬롯 수입니다. 기본값은 블리자드 글꼴을 사용합니다."
L["The number on a group buff's icon: how many are missing it, out of how many."] = "그룹 강화 효과 아이콘에 표시되는 숫자입니다. 전체 인원 중 해당 효과가 없는 인원 수를 나타냅니다."
L["The number on each icon."] = "각 아이콘에 표시되는 숫자입니다."
L["The number on the power bar."] = "자원 바에 표시되는 숫자입니다."
L["The numbers in the middle of the XP bar. Pick when they show, then tick any of the numbers. They're split by \" / \"."] = "경험치 바 가운데에 표시되는 숫자입니다. 표시 시점을 선택한 다음 원하는 숫자를 체크하세요. 숫자는 \" / \"로 구분됩니다."
L["The numbers on the health bar."] = "생명력 바에 표시되는 숫자입니다."
L["The numbers on the power bar."] = "자원 바에 표시되는 숫자입니다."
L["The numbers on the XP and reputation bar."] = "경험치 및 평판 바에 표시되는 숫자입니다."
L["The numbers or time left on this bar."] = "이 막대에 표시되는 숫자 또는 남은 시간입니다."
L["The options below need it on."] = "아래 옵션을 사용하려면 이 기능을 켜야 합니다."
L["The pet frame fades with the player frame, using these settings. Pointing at either shows both."] = "이 설정에 따라 소환수 프레임이 플레이어 프레임과 함께 흐려집니다. 둘 중 하나에 마우스를 올리면 두 프레임이 모두 표시됩니다."
L["The picker's opacity slider sets how strong a colour is. Lower it for a softer tint; at 0 On Cooldown leaves the icon alone."] = "색상 선택기의 투명도 슬라이더로 색상의 강도를 조절합니다. 값을 낮추면 색상이 옅어집니다. 0으로 설정하면 재사용 대기시간 중에도 아이콘에 색상을 적용하지 않습니다."
L["The plain pet frame in every style. Off: a small pet frame in Forever or FlareUI Style."] = "모든 스타일에서 기본 소환수 프레임을 사용합니다. 끄면 Forever 또는 FlareUI 스타일에서 작은 소환수 프레임을 사용합니다."
L["The plain target of target and target of focus frames in every style. Off: small frames in Forever or FlareUI Style."] = "모든 스타일에서 기본 대상의 대상 및 주시 대상의 대상 프레임을 사용합니다. 끄면 Forever 또는 FlareUI 스타일에서 작은 프레임을 사용합니다."
L["The plate behind the Info Bar's text. Off shows the text alone, straight on the map."] = "정보 바 텍스트 뒤에 표시되는 배경입니다. 끄면 지도 위에 텍스트만 표시됩니다."
L["The plate's border pulses in the threat colour, with a soft glow round it."] = "이름표 테두리가 위협 수준 색상으로 점멸하며 주변에 은은한 빛 효과가 나타납니다."
L["The plate's whole inside flashes once when a mob turns on you, or away from you as a tank."] = "몬스터가 자신을 공격 대상으로 삼거나, 방어 담당자로서 자신에게서 다른 대상으로 공격을 전환하면 이름표 내부 전체가 한 번 깜박입니다."
L["The portrait on the right, as on the target frame. Off: on the left, as on the player frame."] = "대상 프레임처럼 초상화를 오른쪽에 표시합니다. 끄면 플레이어 프레임처럼 왼쪽에 표시합니다."
L["The portrait ring in percent of its usual size. It keeps its shape, and the frame keeps its height."] = "기본 크기에 대한 백분율로 초상화 고리의 크기를 조정합니다. 고리의 모양과 프레임의 높이는 그대로 유지됩니다."
L["The power bar's height."] = "자원 바의 높이입니다."
L["The profile |cffffff00%s|r was set up on the Edit Mode layout |cffffff00%s|r, which this character doesn't have. FlareUI's frames follow the profile anyway. For Blizzard's bars, copy FlareUI's layout code and import it in Edit Mode (Layout > Import)."] = "프로필 |cffffff00%s|r은 이 캐릭터에 없는 편집 모드 배치 |cffffff00%s|r을 기준으로 설정되었습니다. FlareUI 프레임은 그래도 해당 프로필을 따릅니다. 블리자드 막대에도 적용하려면 FlareUI 배치 코드를 복사해 편집 모드(배치 > 가져오기)에서 가져오세요."
L["The profile |cffffff00%s|r was set up on the Edit Mode layout |cffffff00%s|r, which this character doesn't have. FlareUI's frames follow the profile anyway. For Blizzard's bars, export that layout in Edit Mode on the other character, or turn on Sync Blizz UI (General page)."] = "프로필 |cffffff00%s|r은 이 캐릭터에 없는 편집 모드 배치 |cffffff00%s|r을 기준으로 설정되었습니다. FlareUI 프레임은 그래도 해당 프로필을 따릅니다. 블리자드 막대에도 적용하려면 다른 캐릭터의 편집 모드에서 해당 배치를 내보내거나 일반 페이지에서 블리자드 UI 동기화를 켜세요."
L["The profile |cffffff00%s|r was set up on the Edit Mode layout |cffffff00%s|r. Switch to it?"] = "프로필 |cffffff00%s|r은 편집 모드 배치 |cffffff00%s|r을 기준으로 설정되었습니다. 해당 배치로 전환할까요?"
L["The profile in use."] = "현재 사용 중인 프로필입니다."
L["The quest log can't be opened from the tracker in combat."] = "전투 중에는 추적기에서 퀘스트 목록을 열 수 없습니다."
L["The quest you focus on the map moves to the top. With zone headings, its zone moves up with it."] = "지도에서 주시한 퀘스트가 맨 위로 이동합니다. 지역 제목을 사용하는 경우 해당 퀘스트의 지역도 함께 위로 이동합니다."
L["The quest's level in front of its name."] = "퀘스트 이름 앞에 레벨을 표시합니다."
L["The quick brown fox jumps over the lazy dog"] = "키보드 글꼴 확인용 문장입니다."
L["The radial's button again"] = "방사형 메뉴 버튼 다시 누르기"
L["The raid marker of what each member is targeting, on the right edge of its frame."] = "각 공격대원이 대상으로 지정한 대상의 공격대 징표를 프레임 오른쪽 가장자리에 표시합니다."
L["The raid's main tanks in a small frame of their own (set by the raid leader)."] = "공격대장이 지정한 공격대 주 방어 담당자를 별도의 작은 프레임에 표시합니다."
L["The Remind Before It Ends time inside dungeons. Same as Above uses the time above."] = "던전에서 종료 전 알림을 표시할 시점입니다. 위와 동일을 선택하면 위에 설정한 시간을 사용합니다."
L["The Remind Before It Ends time inside raids. Same as Above uses the time above."] = "공격대에서 종료 전 알림을 표시할 시점입니다. 위와 동일을 선택하면 위에 설정한 시간을 사용합니다."
L["The reminders you hid with a right-click. Untick one to bring it back. None brings them all back."] = "오른쪽 클릭으로 숨긴 알림입니다. 체크를 해제하면 해당 알림을 다시 표시합니다. 없음을 선택하면 모든 알림을 다시 표시합니다."
L["The rest is set up here."] = "나머지 설정은 여기에서 할 수 있습니다."
L["The same number as the unit frames' Threat Text and the nameplates' Threat Percentage."] = "유닛 프레임의 위협 수준 텍스트 및 이름표의 위협 수준 백분율과 동일한 숫자입니다."
L["The scale Custom uses. 100% is Blizzard's default size."] = "사용자 지정에서 사용할 크기 배율입니다. 100%는 블리자드 기본 크기입니다."
L["The seal's icon at the left end of the bar, so you know it at a glance."] = "막대 왼쪽 끝에 인장의 아이콘을 표시해 한눈에 알아볼 수 있게 합니다."
L["The seal's name on the left of the bar."] = "막대 왼쪽에 인장 이름을 표시합니다."
L["The seal's time left on the right of the bar."] = "막대 오른쪽에 인장의 남은 시간을 표시합니다."
L["The seconds left on the right of the bar (and Waiting)."] = "막대 오른쪽에 남은 시간(초)을 표시합니다(대기 중 포함)."
L["The sender's level before their name, when known."] = "확인 가능한 경우 보낸 사람의 이름 앞에 레벨을 표시합니다."
L["The shape of buff and debuff icons on the plates."] = "이름표에 표시되는 강화 효과 및 약화 효과 아이콘의 모양입니다."
L["The shape of buff and debuff icons on unit frames."] = "유닛 프레임에 표시되는 강화 효과 및 약화 효과 아이콘의 모양입니다."
L["The shape of your buff and debuff icons."] = "자신의 강화 효과 및 약화 효과 아이콘의 모양입니다."
L["The size of buff icons. Each row holds as many as fit."] = "강화 효과 아이콘의 크기입니다. 각 행에는 들어갈 수 있는 만큼 표시됩니다."
L["The size of debuff icons and dispel icons. Each row holds as many as fit."] = "약화 효과 및 해제 아이콘의 크기입니다. 각 행에는 들어갈 수 있는 만큼 표시됩니다."
L["The size of debuff icons. Each row holds as many as fit."] = "약화 효과 아이콘의 크기입니다. 각 행에는 들어갈 수 있는 만큼 표시됩니다."
L["The size of every action button. 111% is FlareUI's default."] = "모든 행동 버튼의 크기입니다. 111%가 FlareUI 기본값입니다."
L["The size of every tooltip."] = "모든 툴팁의 크기입니다."
L["The size of the icons, and how many fit in a row."] = "아이콘의 크기와 한 행에 표시할 수 있는 아이콘 수입니다."
L["The size of the plates picked in State."] = "상태에서 선택한 이름표의 크기입니다."
L["The size of the whole interface, for every character:\n* Off: FlareUI leaves it alone, and Blizzard's UI Scale setting works\n* Pixel Perfect: one interface pixel per screen pixel. Very small on a 4K screen\n* 4K, 1440p, 1080p: pixel perfect for that screen (at 125% for Windows' 125% scaling)\n* Custom: any scale, beyond Blizzard's slider\nAny choice but Off replaces Blizzard's UI Scale each time you log in. After a change, you have 15 seconds to keep it, or the old scale comes back."] = "모든 캐릭터에 적용되는 전체 인터페이스 크기입니다.\n* 끄기: FlareUI가 크기를 변경하지 않으며 블리자드 UI 크기 설정이 작동합니다.\n* 픽셀 퍼펙트: 화면 픽셀 하나당 인터페이스 픽셀 하나를 사용합니다. 4K 화면에서는 매우 작게 표시됩니다.\n* 4K, 1440p, 1080p: 해당 해상도에 맞춰 픽셀 퍼펙트로 설정합니다(Windows 배율이 125%인 경우 125%로 적용).\n* 사용자 지정: 블리자드 슬라이더의 범위를 넘어 원하는 배율로 설정합니다.\n끄기 이외의 설정은 로그인할 때마다 블리자드 UI 크기 설정을 대체합니다. 변경 후 15초 안에 설정을 유지해야 하며, 그렇지 않으면 이전 크기로 돌아갑니다."
L["The size of the whole radial, buttons and ring."] = "버튼과 고리를 포함한 방사형 메뉴 전체의 크기입니다."
L["The small icons on the minimap's edge:\n* Sundial: the day/night sundial at the bottom-left corner\n* Group Finder: a small queue icon in place of Blizzard's large eye, while you're queued\n* Vehicle Exit: leaves a vehicle or ends a flight early, while you can\n* Durability Warning: Blizzard's durability figure as one icon, yellow or red when gear is about to break"] = "미니맵 가장자리에 표시되는 작은 아이콘입니다.\n* Sundial: 왼쪽 아래 모서리에 낮과 밤을 표시하는 해시계입니다.\n* 파티 찾기: 대기열에 등록되어 있는 동안 블리자드의 큰 눈 아이콘 대신 작은 대기열 아이콘을 표시합니다.\n* 탈것에서 내리기: 가능한 경우 탈것에서 내리거나 비행을 조기에 종료합니다.\n* 내구도 경고: 블리자드의 내구도 표시를 하나의 아이콘으로 나타내며, 장비가 파손되기 직전이면 노란색 또는 빨간색으로 표시합니다."
L["The spell ID of the aura to add. Wowhead shows it in the spell's web address."] = "추가할 오라의 주문 ID입니다. Wowhead 주문 페이지의 웹 주소에서 확인할 수 있습니다."
L["The spell name, its time and its target."] = "주문 이름과 지속 시간, 대상입니다."
L["The spell's icon left of the cast bar."] = "시전 바 왼쪽에 표시되는 주문 아이콘입니다."
L["The spell's icon, left of the bar."] = "막대 왼쪽에 표시되는 주문 아이콘입니다."
L["The spell's name on the cast bar."] = "시전 바에 표시되는 주문 이름입니다."
L["The stack count on buffs and debuffs. Auto sizes it to the icon."] = "강화 효과와 약화 효과의 중첩 횟수입니다. 아이콘 크기에 맞춰 자동으로 조정됩니다."
L["The stack count on each icon."] = "각 아이콘에 표시되는 중첩 횟수입니다."
L["The stack counts and cooldown numbers on your bag items. Default keeps Blizzard's font."] = "가방 아이템에 표시되는 중첩 횟수와 재사용 대기시간 숫자입니다. 기본값은 블리자드 글꼴을 사용합니다."
L["The swing's name on the left of the bar."] = "막대 왼쪽에 표시되는 공격 이름입니다."
L["The switch did not go through. Use Blizzard's Settings > Gamepad > Enable Gamepad UI."] = "전환하지 못했습니다. 블리자드 설정 > 게임패드 > 게임패드 UI 활성화를 사용하세요."
L["The symbol of each debuff type you can dispel (Magic, Curse, Disease, Poison)."] = "해제할 수 있는 각 약화 효과 유형의 표시입니다(마법, 저주, 질병, 독)."
L["The tank's percent on the Threat tab is its threat against second place: 200% is twice theirs, and near 100% they're about to take it. Off: the tank always shows 100%."] = "위협 수준 탭에 표시되는 방어 담당자의 백분율은 2위 대상에 대한 위협 수준을 나타냅니다. 200%는 2위 대상의 두 배이며, 100%에 가까우면 어그로를 빼앗길 수 있습니다. 끄면 방어 담당자는 항상 100%로 표시됩니다."
L["The target's combo points:\n* Modern Style: a bar along the top of the health bar\n* FlareUI Style: Off, Classic or Modern"] = "대상의 연계 점수입니다.\n* Modern 스타일: 생명력 바 위쪽에 막대로 표시합니다.\n* FlareUI 스타일: 끄기, 클래식 또는 모던 중에서 선택합니다."
L["The text in the Info Bar at the bottom of the map."] = "지도 아래쪽 정보 바에 표시되는 텍스트입니다."
L["The text in the loot roll window. The size is for item names; the smaller lines are two sizes smaller."] = "전리품 주사위 창에 표시되는 텍스트입니다. 설정한 크기는 아이템 이름에 적용되며, 나머지 작은 줄은 두 단계 더 작게 표시됩니다."
L["The text size."] = "텍스트 크기입니다."
L["The texture of the meter's bars. Blizzard keeps the game's own."] = "측정기 막대의 질감입니다. 블리자드를 선택하면 게임 기본 질감을 사용합니다."
L["The texture of the shield (absorb) over the health bar."] = "생명력 바 위에 표시되는 보호막(흡수)의 질감입니다."
L["The time left on buffs and debuffs. Auto sizes it to the icon."] = "강화 효과와 약화 효과의 남은 시간입니다. 아이콘 크기에 맞춰 자동으로 조정됩니다."
L["The time left on each icon."] = "각 아이콘에 표시되는 남은 시간입니다."
L["The time left on the cast bar."] = "시전 바에 표시되는 남은 시간입니다."
L["The time left on the cast, at the bar's right end."] = "막대 오른쪽 끝에 표시되는 시전 남은 시간입니다."
L["The time left on the right of the bar."] = "막대 오른쪽에 표시되는 남은 시간입니다."
L["The time left on the right of the bar. A route you haven't flown yet counts up while it's learned."] = "막대 오른쪽에 표시되는 남은 시간입니다. 아직 비행하지 않은 경로는 경로를 익히는 동안 시간이 증가합니다."
L["The time left, at the right end of the bar."] = "막대 오른쪽 끝에 표시되는 남은 시간입니다."
L["The time on the map's clock."] = "지도 시계에 표시되는 시간입니다."
L["The timer's name on the left of the bar."] = "막대 왼쪽에 표시되는 타이머 이름입니다."
L["The title row: Damage Meter or Threat, the session and its timer."] = "제목 표시줄입니다. 피해량 측정기 또는 위협 수준, 세션 및 타이머를 표시합니다."
L["The title under the name: a player's title, or an NPC's role such as General Goods."] = "이름 아래에 표시되는 칭호입니다. 플레이어의 칭호 또는 일반 상품 상인과 같은 NPC의 역할을 표시합니다."
L["The totems come with FlareUI's player frame."] = "토템은 FlareUI 플레이어 프레임에 포함되어 표시됩니다."
L["The tracker's size:\n* Width\n* Max Height: how tall it grows before it scrolls\n* Quest Spacing: the gap between quests"] = "추적기의 크기입니다.\n* 너비\n* 최대 높이: 스크롤이 시작되기 전까지 확장되는 높이입니다.\n* 퀘스트 간격: 퀘스트 사이의 간격입니다."
L["The tracker's text colours:\n* Blizzard: the game's own yellow titles and bright colours\n* FlareUI: bronze header and quest titles, and softer tones for every other colour"] = "추적기 텍스트의 색상입니다.\n* 블리자드: 게임 기본 노란색 제목과 선명한 색상을 사용합니다.\n* FlareUI: 청동색 머리글과 퀘스트 제목을 사용하고, 나머지 색상은 더 부드러운 색조로 표시합니다."
L["The tracker's title and its headers."] = "추적기의 제목과 머리글입니다."
L["The typeface. Global follows the Global Font on the General page."] = "글꼴 종류입니다. 전역을 선택하면 일반 페이지의 전역 글꼴 설정을 따릅니다."
L["The unit frames' bar effects, as many as you like:\n* Bar Animations: health glides to its new value\n* Bar Edge Glow: a glow at the front of the bar\n* Damage Trail: lost health fades away behind the bar"] = "원하는 만큼 유닛 프레임 막대 효과를 사용할 수 있습니다.\n* 막대 애니메이션: 생명력 막대가 새 수치까지 부드럽게 이동합니다.\n* 막대 가장자리 광채: 막대 앞쪽에 빛 효과를 표시합니다.\n* 피해 잔상: 감소한 생명력이 막대 뒤에서 서서히 사라집니다."
L["The unit's level next to its name."] = "유닛 이름 옆에 레벨을 표시합니다."
L["The unit's level. Its size follows the name in Modern Style and the level disc in the portrait styles."] = "유닛의 레벨입니다. Modern 스타일에서는 이름 크기를 따르고, 초상화 스타일에서는 레벨 원형 표시의 크기를 따릅니다."
L["The unit's name on the bar and above the plate."] = "막대와 이름표 위에 표시되는 유닛 이름입니다."
L["The unit's name."] = "유닛의 이름입니다."
L["The units picked here leave Name Only Mode while you're in a fight and show their whole plate. Their options stay open to set that plate."] = "여기에서 선택한 유닛은 전투 중 이름만 표시 모드에서 벗어나 전체 이름표를 표시합니다. 해당 이름표를 설정할 수 있도록 관련 옵션도 계속 활성화됩니다."
L["The whole inside of the cast bar, icon too, flashes red while the spell is aimed at you."] = "주문이 자신을 대상으로 시전되는 동안 시전 바 내부 전체와 아이콘이 빨간색으로 깜박입니다."
L["The world map turns see-through while you move."] = "이동하는 동안 세계 지도가 반투명해집니다."
L["The XP your quests will give, in gold on the XP bar. Quests in progress show paler. The total also shows in the bar's text."] = "퀘스트로 획득할 경험치를 경험치 바에 금색으로 표시합니다. 진행 중인 퀘스트는 더 옅게 표시됩니다. 총 경험치도 막대의 텍스트에 표시됩니다."
L["The zone name that appears as you enter a new area. Default keeps Blizzard's font. The size stays the same."] = "새 지역에 진입할 때 표시되는 지역 이름입니다. 기본값은 블리자드 글꼴을 사용하며 크기는 변경되지 않습니다."
L["The zone's name above the map."] = "지도 위에 표시되는 지역 이름입니다."
L["There's already a profile with that name."] = "같은 이름의 프로필이 이미 있습니다."
L["These only work outside dungeons, raids and battlegrounds."] = "이 기능은 던전, 공격대 및 전장 밖에서만 작동합니다."
L["These options need `Combined Backpack` on."] = "이 옵션을 사용하려면 `통합 배낭`을 켜야 합니다."
L["These settings are disabled in Gamepad mode due to Blizzard restrictions."] = "블리자드의 제한으로 인해 게임패드 모드에서는 이 설정을 사용할 수 없습니다."
L["These start off: pick them in /fui, Bags & Looting."] = "이 기능들은 기본적으로 꺼져 있습니다. /fui의 가방 및 전리품 메뉴에서 선택하세요."
L["Thick Borders"] = "두꺼운 테두리"
L["Thick Outline"] = "두꺼운 윤곽선"
L["Thin Borders"] = "얇은 테두리"
L["This character gets its own key for this radial. Your other characters keep the shared key."] = "이 캐릭터는 이 방사형 메뉴에 별도의 키를 사용합니다. 다른 캐릭터는 기존 공유 키를 그대로 사용합니다."
L["This client does not let addons reload the UI. Type |cffffff00/reload|r to apply the change."] = "현재 게임 클라이언트에서는 애드온이 UI를 다시 불러올 수 없습니다. 변경 사항을 적용하려면 |cffffff00/reload|r을 입력하세요."
L["This is the game's own setting. FlareUI only changes it once you move the slider."] = "이 설정은 게임 자체 설정입니다. 슬라이더를 움직여야 FlareUI가 변경합니다."
L["This is the one thing to remember: there are two places."] = "기억해야 할 점은 한 가지입니다. 위치가 두 곳이라는 것입니다."
L["This reloads your interface."] = "인터페이스를 다시 불러옵니다."
L["This type's plates can't be clicked; clicks go to the world."] = "이 유형의 이름표는 클릭할 수 없습니다. 클릭하면 게임 세계에 입력됩니다."
L["This Unit Type"] = "이 유닛 유형"
L["This unit's plates show only the name: no bar, cast bar or auras. This unit's other options grey out."] = "이 유닛의 이름표에는 막대, 시전 바 또는 오라 없이 이름만 표시됩니다. 이 유닛의 다른 옵션은 비활성화됩니다."
L["Those in Your Bags"] = "가방에 있는 항목"
L["Threat"] = "위협 수준"
L["Threat as a Tank"] = "방어 담당자 위협 수준"
L["Threat as Damage or Healer"] = "공격 및 치유 담당자 위협 수준"
L["Threat Bars"] = "위협 수준 막대"
L["Threat colours only show while the mob is fighting. A mob your pet holds gets the Another Tank Has It colour."] = "위협 수준 색상은 몬스터가 전투 중일 때만 표시됩니다. 소환수가 어그로를 잡고 있는 몬스터에는 다른 방어 담당자가 보유 중일 때의 색상이 적용됩니다."
L["Threat colours win over mob type colours. Pick each colour in Nameplate Colours."] = "위협 수준 색상은 몬스터 유형 색상보다 우선 적용됩니다. 각 색상은 이름표 색상에서 선택하세요."
L["Threat Glow"] = "위협 수준 광채"
L["Threat is hidden here"] = "위협 수준이 여기에 숨겨져 있습니다"
L["Threat Meter"] = "위협 수준 측정기"
L["Threat Percentage"] = "위협 수준 백분율"
L["Threat Scale"] = "위협 수준 크기"
L["Threat Text"] = "위협 수준 텍스트"
L["Threat Window"] = "위협 수준 창"
L["Ticked Ones"] = "선택된 항목"
L["Tidies your bags each time you open them, as the broom button does. Bags set to Ignore This Bag are left alone."] = "빗자루 버튼과 마찬가지로 가방을 열 때마다 정리합니다. 이 가방 무시로 설정한 가방은 정리하지 않습니다."
L["Tight Spacing"] = "좁은 간격"
L["Time Left"] = "남은 시간"
L["Time Left puts auras about to end first, permanent ones last."] = "남은 시간을 기준으로 정렬하면 곧 끝나는 오라가 먼저, 영구 오라가 마지막에 배치됩니다."
L["Time to level"] = "레벨 업까지 남은 시간"
L["Time's up!"] = "시간이 끝났습니다!"
L["Timer Colour"] = "타이머 색상"
L["Timers turn yellow under 10 seconds and red under 5."] = "타이머는 남은 시간이 10초 미만이면 노란색, 5초 미만이면 빨간색으로 바뀝니다."
L["Timing"] = "시간 설정"
L["Tint Health"] = "생명력 색조 적용"
L["Tip:"] = "팁:"
L["Title"] = "제목"
L["To everyone who downloaded FlareUI, sent feedback, reported bugs or helped a friend set it up: thank you. FlareUI gets better every week because of you."] = "FlareUI를 다운로드하고, 의견을 보내고, 버그를 신고하거나 친구의 설정을 도와주신 모든 분께 감사드립니다. 여러분 덕분에 FlareUI는 매주 더 나아지고 있습니다."
L["To next level"] = "다음 레벨까지"
L["To put it on the player frame instead, turn on Cast Bar in the player frame's Edit Mode options, and set this bar's Visibility to Never in Edit Mode. Never hides Blizzard's cast bar too."] = "대신 플레이어 프레임에 표시하려면 플레이어 프레임의 편집 모드 옵션에서 시전 바를 켜고, 편집 모드에서 이 막대의 표시 여부를 항상 숨김으로 설정하세요. 항상 숨김은 블리자드 시전 바도 숨깁니다."
L["Toggle"] = "전환"
L["Toggle Edit Mode Overlays"] = "편집 모드 오버레이 전환"
L["Toggle Fake CM setup mode."] = "가짜 재사용 대기시간 관리자 설정 모드를 전환합니다."
L["Toggle Threat Meter"] = "위협 수준 측정기 전환"
L["Toggle: middle-click a nested radial to open it in place. The mouse wheel still steps through it."] = "전환: 하위 방사형 메뉴를 가운데 클릭하면 현재 위치에서 엽니다. 마우스 휠로도 계속 항목을 이동할 수 있습니다."
L["Tooltip borders in the colour of:\n* A player's class\n* A creature's reaction\n* An item's quality"] = "툴팁 테두리 색상을 다음 항목에 따라 지정합니다.\n* 플레이어의 직업\n* 생명체의 반응 상태\n* 아이템의 품질"
L["Tooltip Corner"] = "툴팁 모서리"
L["Tooltips"] = "툴팁"
L["Tooltips on the buff and debuff icons of party and raid frames. Never: pointing at an icon counts as pointing at the frame."] = "파티 및 공격대 프레임의 강화 효과와 약화 효과 아이콘에 툴팁을 표시합니다. 항상 숨김을 선택하면 아이콘에 마우스를 올리는 동작도 프레임에 마우스를 올린 것으로 처리됩니다."
L["Tooltips show here. Drag this to move them."] = "툴팁이 여기에 표시됩니다. 드래그하여 위치를 옮기세요."
L["Top"] = "위"
L["Top %d"] = "상위 %d위"
L["Top Left"] = "왼쪽 위"
L["Top Right"] = "오른쪽 위"
L["Totem Bar"] = "토템 바"
L["Totems"] = "토템"
L["Totems per Row"] = "한 행의 토템 수"
L["Toys"] = "장난감"
L["Tracked Bars"] = "추적 막대"
L["Tracked Recipes"] = "추적 중인 제작법"
L["Tracked recipes, with the reagents you carry."] = "소지한 재료와 함께 추적 중인 제작법을 표시합니다."
L["Trade"] = "거래"
L["Trade - City"] = "거래 - 도시"
L["Train All"] = "모두 배우기"
L["Train All Skills"] = "모든 기술 배우기"
L["Transmog"] = "형상변환"
L["Trivial"] = "매우 쉬움"
L["Try again after the fight."] = "전투가 끝난 후 다시 시도하세요."
L["Try These Next"] = "다음 항목을 사용해 보세요"
L["Turn It On"] = "켜기"
L["Turn On"] = "켜기"
L["turn on the Damage Meter in the FlareUI settings (and Blizzard's damage meter) to use the threat view."] = "위협 수준 보기를 사용하려면 FlareUI 설정과 블리자드 피해량 측정기에서 피해량 측정기를 켜세요."
L["Turning it off restores your own setting."] = "끄면 기존 설정이 복원됩니다."
L["Turning it on or off reloads the interface. Changing the shape doesn't."] = "켜거나 끄면 인터페이스를 다시 불러옵니다. 모양을 변경할 때는 다시 불러오지 않습니다."
L["Turns Blizzard's Cooldown Manager on. The same switch as in the game's options."] = "블리자드 재사용 대기시간 관리자를 켭니다. 게임 옵션에 있는 것과 동일한 설정입니다."
L["Turns FlareUI's UI Scale off, back to Blizzard's own scale."] = "FlareUI UI 크기 설정을 끄고 블리자드 기본 크기로 되돌립니다."
L["Turns the order around: newest, longest left or Z first."] = "정렬 순서를 반대로 바꿉니다. 최신순, 남은 시간이 긴 순 또는 Z부터 정렬합니다."
L["Turns the order around."] = "정렬 순서를 반대로 바꿉니다."
L["Tweaks"] = "세부 조정"
L["Two windows that match, usually in the bottom corners of your screen."] = "서로 짝을 이루는 두 개의 창으로, 보통 화면 아래쪽 양 모서리에 배치됩니다."
L["Type /way and coordinates to pin a spot on the map."] = "/way와 좌표를 입력하면 지도에 위치를 표시할 수 있습니다."
L["Type |cffffd100/fui|r in chat. Turn parts of FlareUI on or off, and find everything that isn't a frame on your screen: chat options, tooltips, the radial menu."] = "채팅창에 |cffffd100/fui|r를 입력하세요. FlareUI의 각 기능을 켜거나 끌 수 있으며, 화면의 프레임 외 요소인 채팅 옵션, 툴팁, 방사형 메뉴 등을 찾을 수 있습니다."
L["Type |cffffd100/fui|r whenever you want to change something"] = "무언가를 변경하고 싶을 때 언제든지 |cffffd100/fui|r를 입력하세요."
L["Typing always shows the chat."] = "입력하면 항상 채팅창이 표시됩니다."
L["Typing always shows the chat.\nNew Messages: a new line, or closing a quest or vendor window, brings it back.\nOnly Chat Messages: only lines people write. Loot, skill-ups and XP stay quiet."] = "입력하면 항상 채팅창이 표시됩니다.\n새 메시지: 새 메시지가 도착하거나 퀘스트 또는 상인 창을 닫으면 채팅창이 다시 표시됩니다.\n채팅 메시지만: 다른 사람이 작성한 메시지만 표시합니다. 전리품, 기술 숙련도 상승 및 경험치 메시지는 표시하지 않습니다."
L["UI Scale"] = "UI 크기"
L["UI scale %.2f (yours %.2f)"] = "UI 크기 %.2f (현재 설정: %.2f)"
L["UI Scale is Off: Blizzard's own scale is back."] = "UI 크기가 꺼져 있습니다. 블리자드 기본 크기로 돌아갔습니다."
L["unavailable"] = "사용할 수 없음"
L["Uncollected Appearances"] = "수집하지 않은 형상"
L["Under the Icon"] = "아이콘 아래"
L["Undo Changes"] = "변경 사항 되돌리기"
L["Ungroup"] = "그룹 해제"
L["Uninterruptible"] = "차단 불가"
L["Unit"] = "유닛"
L["Unit Frames"] = "유닛 프레임"
L["Unit frames and bars are set up here."] = "유닛 프레임과 막대를 여기에서 설정합니다."
L["Units and objects in the world."] = "게임 세계의 유닛과 오브젝트입니다."
L["Unmute Tab"] = "탭 음소거 해제"
L["Unpin"] = "고정 해제"
L["Until you pick a palette here, the bars follow the unit frames' palette."] = "여기에서 팔레트를 선택하기 전까지 막대는 유닛 프레임의 팔레트를 따릅니다."
L["Unusable"] = "사용 불가"
L["Up"] = "위"
L["Update Spell Ranks"] = "주문 등급 업데이트"
L["Upkeep"] = "유지"
L["Use FlareUI's unit frames"] = "FlareUI 유닛 프레임 사용"
L["Use Global Font"] = "전역 글꼴 사용"
L["Use Global Font Everywhere"] = "모든 곳에서 전역 글꼴 사용"
L["Use It"] = "사용"
L["Use Our Layout"] = "기본 배치 사용"
L["Use Quality of Life"] = "편의 기능 사용"
L["Use the Game Language"] = "게임 언어 사용"
L["use the last button"] = "마지막 버튼 사용"
L["use the lit button"] = "강조 표시된 버튼 사용"
L["Use the mouse for this list."] = "이 목록에서는 마우스를 사용하세요."
L["Uses your class's own spells, so it means range for you."] = "자신의 직업 전용 주문을 사용하므로 자신의 사거리를 기준으로 판단합니다."
L["Value"] = "값"
L["Value [Max]"] = "현재 값 [최대값]"
L["Value | Health Lost"] = "값 | 잃은 생명력"
L["Value | Percent"] = "값 | 백분율"
L["Value and Percent"] = "값 및 백분율"
L["Values on Mouseover"] = "마우스 오버 시 수치 표시"
L["Vehicle Exit"] = "탈것에서 내리기"
L["Vendor"] = "상인"
L["Vendors show 20 items a page instead of 10, in four columns."] = "상인 창에서 한 페이지에 10개 대신 20개의 아이템을 네 개의 열로 표시합니다."
L["Version, credits and what's new on FlareUI."] = "FlareUI의 버전, 제작진 및 새 소식입니다."
L["Version: %s"] = "버전: %s"
L["Vertical"] = "세로"
L["Visibility"] = "표시 여부"
L["Voice Button"] = "음성 버튼"
L["Volume"] = "음량"
L["Waiting"] = "대기 중"
L["Waiting State"] = "대기 상태"
L["Want your screen set up like ours? Import the FlareUI layout into Edit Mode:"] = "화면을 저희와 똑같이 설정하고 싶으신가요? 편집 모드에서 FlareUI 배치를 가져오세요."
L["Want your screen set up like ours? Import the FlareUI layout into Edit Mode:\n\n`1.` Click `Copy Layout Code` and press `Ctrl+C`.\n`2.` Press `Esc` and choose `Edit Mode`.\n`3.` Open the `Layout` menu and choose `Import`.\n`4.` Paste with `Ctrl+V`, name it and click `Import`."] = "화면을 저희와 똑같이 설정하고 싶으신가요? 편집 모드에서 FlareUI 배치를 가져오세요.\n\n`1.` `배치 코드 복사`를 클릭하고 `Ctrl+C`를 누릅니다.\n`2.` `Esc`를 누르고 `편집 모드`를 선택합니다.\n`3.` `배치` 메뉴를 열고 `가져오기`를 선택합니다.\n`4.` `Ctrl+V`로 붙여넣고 이름을 입력한 다음 `가져오기`를 클릭합니다."
L["Warriors: Action Bar 1 keeps the same buttons in every stance."] = "전사: 모든 태세에서 행동 단축바 1의 버튼 구성이 동일하게 유지됩니다."
L["Weapon Buffs"] = "무기 강화 효과"
L["Weapon Oil / Stone"] = "무기 오일 / 숫돌"
L["Welcome to FlareUI!"] = "FlareUI에 오신 것을 환영합니다!"
L["Welcome!"] = "환영합니다!"
L["Westfall"] = "서부 몰락지대"
L["What a Profile Saves"] = "프로필에 저장되는 항목"
L["What each button does while a radial is open. The camera holds still while you aim."] = "방사형 메뉴가 열려 있을 때 각 버튼의 기능입니다. 조준하는 동안 카메라는 움직이지 않습니다."
L["What each main tank is targeting, in a small frame below or right of theirs."] = "각 주 방어 담당자가 대상으로 지정한 대상을 해당 프레임 아래쪽 또는 오른쪽의 작은 프레임에 표시합니다."
L["What each member is targeting, in a small frame under theirs or beside it. Click one to target it too."] = "각 파티원의 대상이 해당 프레임 아래쪽 또는 옆의 작은 프레임에 표시됩니다. 클릭하면 해당 대상도 대상으로 지정합니다."
L["What lights up on the plate under your mouse, a little softer than your target's:\n* Border: a lighter border\n* Bar: a light over the bar\n* Outer Glow: the soft glow round the plate"] = "마우스를 올린 이름표에 표시되는 강조 효과입니다. 대상의 강조 효과보다 조금 약하게 표시됩니다.\n* 테두리: 더 밝은 테두리를 표시합니다.\n* 막대: 막대 위에 밝은 효과를 표시합니다.\n* 외곽 광채: 이름표 주변에 은은한 빛을 표시합니다."
L["What shows in the portrait circle."] = "초상화 원 안에 표시할 항목입니다."
L["What the icons show:\n* Glow When Missing: a gold glow round a missing buff\n* Glow When Running Out: an orange glow round a buff about to run out\n* Time Left: the time left on a buff about to run out, at the top of its icon"] = "아이콘에 표시되는 정보:\n* 없을 때 광채 표시: 없는 강화 효과 주위에 금색 광채 표시\n* 만료 임박 시 광채 표시: 곧 만료될 강화 효과 주위에 주황색 광채 표시\n* 남은 시간: 곧 만료될 강화 효과의 남은 시간을 아이콘 위에 표시"
L["What the left side of the Info Bar shows."] = "정보 바 왼쪽에 표시할 항목."
L["What the left, middle and right of the bar show. Several numbers show together, split by /, in the order you tick them. A name stands alone."] = "바의 왼쪽, 가운데, 오른쪽에 표시할 항목. 여러 숫자는 선택한 순서대로 /로 구분하여 함께 표시됩니다. 이름은 단독으로 표시됩니다."
L["What the middle of the bar shows. Several numbers show together, split by /."] = "바 가운데에 표시할 항목. 여러 숫자는 /로 구분하여 함께 표시됩니다."
L["What the middle of the Info Bar shows."] = "정보 바 가운데에 표시할 항목."
L["What the right side of the Info Bar shows."] = "정보 바 오른쪽에 표시할 항목."
L["What the Threat tab shows beside each name."] = "위협 수준 탭에서 각 이름 옆에 표시할 항목."
L["What you have on you, and what you're missing."] = "현재 보유한 것과 부족한 것."
L["What you loot floats up beside your cursor or a spot you choose, so you don't have to read the chat. Each icon has a border in the item's quality colour, square or round."] = "획득한 전리품이 채팅창을 확인하지 않아도 되도록 커서 옆이나 지정한 위치에 떠오릅니다. 각 아이콘에는 아이템 품질에 해당하는 색상의 사각형 또는 원형 테두리가 표시됩니다."
L["What you turned on"] = "활성화한 항목"
L["What you type."] = "입력하는 내용."
L["What's left to do on that enemy, such as 3/8, beside the quest mark, or in its place with Quest Objective off."] = "해당 적에게 남은 퀘스트 목표를 3/8과 같은 형식으로 퀘스트 표시 옆에 보여줍니다. 퀘스트 목표 표시를 끄면 퀘스트 표시 대신 나타납니다."
L["What's New"] = "새로운 기능"
L["When and Where"] = "표시 시점 및 위치"
L["When auto attack is on but you can't swing (the target is out of reach), the bar shows full and grey, with Waiting."] = "자동 공격이 활성화되어 있지만 대상이 사거리 밖에 있어 공격할 수 없을 때, 바가 회색으로 가득 찬 상태로 표시되고 대기 중이라고 나타납니다."
L["When the bar shows. Any ticked condition shows it."] = "바가 표시되는 조건. 선택한 조건 중 하나라도 충족되면 표시됩니다."
L["When the chat shows. Any ticked condition shows it.\n* New Messages: a new line, or closing a quest or vendor window, brings it back\n* Only Chat Messages: only lines people write (say, party, guild, whispers, channels). Loot, skill-ups and XP stay quiet\n* Popped-out windows fade on their own"] = "채팅창이 표시되는 조건. 선택한 조건 중 하나라도 충족되면 표시됩니다.\n* 새 메시지: 새 메시지가 입력되거나 퀘스트 또는 상인 창을 닫으면 다시 나타납니다.\n* 채팅 메시지만: 일반 대화, 파티, 길드, 귓속말, 채널 등 플레이어가 작성한 메시지만 표시합니다. 전리품, 기술 숙련도 상승 및 경험치 알림은 표시하지 않습니다.\n* 분리된 창은 자동으로 희미해집니다."
L["When the Fake CM bars show. Any ticked condition shows them."] = "가짜 재사용 대기시간 관리자 바가 표시되는 조건. 선택한 조건 중 하나라도 충족되면 표시됩니다."
L["When the meter or the threat window shows. Any ticked condition shows it.\n* Never: the meter shows only in Edit Mode, or at its Faded Opacity\n* In an Instance: in dungeons, raids, battlegrounds and arenas\n* Same as Meter: the threat window shows and fades with the meter"] = "측정기 또는 위협 수준 창이 표시되는 조건. 선택한 조건 중 하나라도 충족되면 표시됩니다.\n* 표시 안 함: 측정기는 편집 모드에서만 표시되거나 설정된 투명도로 희미하게 표시됩니다.\n* 인스턴스 내: 던전, 공격대, 전장 및 투기장에서 표시됩니다.\n* 측정기와 동일: 위협 수준 창이 측정기와 함께 표시되고 희미해집니다."
L["When the tracker minimizes itself:\n* In Instances: dungeons, raids, battlegrounds and arenas\n* In Combat: during fights\n* On Flight Paths: while you fly a flight path\nIt opens again when that ends."] = "추적기가 자동으로 최소화되는 조건:\n* 인스턴스 내: 던전, 공격대, 전장 및 투기장에 있을 때\n* 전투 중: 전투 중일 때\n* 비행 경로 이용 중: 비행 경로를 따라 이동할 때\n해당 상황이 끝나면 다시 열립니다."
L["When this bar shows. Any ticked condition shows it."] = "이 바가 표시되는 조건. 선택한 조건 중 하나라도 충족되면 표시됩니다."
L["When you craft several of the same item, your cast bar shows the time left for all of them in brackets after the timer, like 0:12 (1:02)."] = "같은 아이템을 여러 개 제작할 때, 시전 바의 타이머 뒤에 전체 제작에 남은 시간을 괄호로 표시합니다. 예: 0:12 (1:02)."
L["When your threat on the unit shows as a number, in a small box beside the plate:\n* In a Group: only in a party or raid\n* In an Instance: only in dungeons, raids, battlegrounds and arenas\n* Always: solo too\nIt shows only while you have threat. The box sits on the side away from the level, or on the right with no level. Coloured as the unit frames' Threat Text."] = "해당 유닛에 대한 위협 수준을 이름표 옆의 작은 상자에 숫자로 표시하는 조건:\n* 파티 내: 파티 또는 공격대에 속해 있을 때만 표시됩니다.\n* 인스턴스 내: 던전, 공격대, 전장 및 투기장에서만 표시됩니다.\n* 항상: 혼자 있을 때도 표시됩니다.\n위협 수준이 있을 때만 표시됩니다. 상자는 레벨 표시의 반대쪽에 배치되며, 레벨이 표시되지 않으면 오른쪽에 배치됩니다. 유닛 프레임의 위협 수준 텍스트와 같은 색상으로 표시됩니다."
L["Where"] = "위치"
L["Where auras sit around the frame."] = "프레임 주변에서 오라가 표시될 위치."
L["Where Buffs and Debuffs sit when both are on:\n* One Line: side by side, half the plate each\n* Buffs on Top, Debuffs on Top: each on its own line, the plate's full width, one line at most"] = "강화 효과와 약화 효과가 모두 표시될 때의 배치:\n* 한 줄: 이름표 너비의 절반씩 차지하며 나란히 표시됩니다.\n* 강화 효과 위쪽, 약화 효과 위쪽: 각각 별도의 줄에 이름표 전체 너비를 사용하여 표시됩니다. 각 항목은 최대 한 줄까지 표시됩니다."
L["Where do the options live?"] = "설정은 어디에 있나요?"
L["Where each kind of aura sits."] = "각 종류의 오라가 표시될 위치."
L["Where it shows is set by Consumables on the When and Where tab, as for Food and Flask."] = "표시 위치는 음식 및 영약과 마찬가지로 표시 시점 및 위치 탭의 소모품 설정에서 지정합니다."
L["Where Placed"] = "지정한 위치"
L["Where reminders show for a missing, dead or hurt pet."] = "소환수가 없거나 죽었거나 부상을 입었을 때 알림이 표시될 위치."
L["Where reminders show for food, flasks and elixirs."] = "음식, 영약 및 비약 알림이 표시될 위치."
L["Where reminders show for weapon buffs: poisons, imbues, stones and oils."] = "독, 무기 강화 효과, 숫돌 및 오일 등 무기 강화 효과 알림이 표시될 위치."
L["Where reminders show for your class's own buffs."] = "직업 전용 강화 효과 알림이 표시될 위치."
L["Where the arrows sit: on both sides of the plate, on one side, or above it pointing down."] = "화살표의 위치. 이름표 양쪽, 한쪽 또는 이름표 위에서 아래를 가리키도록 표시할 수 있습니다."
L["Where the cast bar sits."] = "시전 바의 위치."
L["Where the feed appears:\n* At the Cursor: beside the pointer, where you looted\n* Where Placed: where you put it in Edit Mode"] = "전리품 목록이 표시될 위치:\n* 커서 위치: 전리품을 획득한 커서 옆에 표시됩니다.\n* 지정한 위치: 편집 모드에서 배치한 위치에 표시됩니다."
L["Where the mob type colours show."] = "몹 유형 색상이 표시될 위치."
L["Where the radial opens:\n* Mouse Cursor: where your mouse is\n* Screen Centre: the middle of the screen"] = "방사형 메뉴가 열리는 위치:\n* 마우스 커서: 마우스가 있는 위치\n* 화면 중앙: 화면 한가운데"
L["Where the reminders show: alone, in a party, in a raid. They always hide in fights."] = "알림이 표시될 위치. 혼자 있을 때, 파티에 있을 때 또는 공격대에 있을 때 표시됩니다. 전투 중에는 항상 숨겨집니다."
L["Where the time left shows on aura icons on the plates."] = "이름표의 오라 아이콘에 남은 시간이 표시될 위치."
L["Where the time left shows on unit frame auras."] = "유닛 프레임 오라에 남은 시간이 표시될 위치."
L["Where the time left shows."] = "남은 시간이 표시될 위치."
L["Where the unit's level shows:\n* Box or Disc: on that side of the bar, as tall as the plate\n* Follow Name: in front of the name"] = "유닛의 레벨이 표시될 위치:\n* 상자 또는 원형: 바의 해당 쪽에 이름표 높이만큼 표시됩니다.\n* 이름 따라가기: 이름 앞에 표시됩니다."
L["Where threat shows besides the meter's Threat tab:\n* Off: only on the Threat tab\n* Separate Window: in its own window. Move and size it in Edit Mode\n* In the Meter in Combat: the meter shows threat during fights, damage after"] = "측정기의 위협 수준 탭 외에 위협 수준이 표시될 위치:\n* 끄기: 위협 수준 탭에만 표시됩니다.\n* 별도 창: 별도의 창에 표시됩니다. 편집 모드에서 위치와 크기를 조정할 수 있습니다.\n* 전투 중 측정기에 표시: 전투 중에는 측정기에 위협 수준을 표시하고, 전투가 끝나면 피해량을 표시합니다."
L["Where you are, and what you're doing there."] = "현재 위치와 그곳에서 하고 있는 활동."
L["Where you type."] = "입력할 위치."
L["Where you're flying, on the left of the bar."] = "바 왼쪽에 현재 비행 중인 목적지를 표시합니다."
L["Where your totems show their time left."] = "토템의 남은 시간이 표시될 위치."
L["Whether enemies get a plate:\n* Always: whenever they're in view\n* In Combat: only during fights"] = "적에게 이름표를 표시할지 여부:\n* 항상: 적이 시야에 들어올 때마다 표시됩니다.\n* 전투 중: 전투 중에만 표시됩니다."
L["Whether friends get a plate:\n* Always: whenever they're in view\n* In Combat: only during fights, so you see who is low without them cluttering the world"] = "아군에게 이름표를 표시할지 여부:\n* 항상: 아군이 시야에 들어올 때마다 표시됩니다.\n* 전투 중: 전투 중에만 표시됩니다. 평소에는 화면을 복잡하게 만들지 않으면서 생명력이 낮은 아군을 확인할 수 있습니다."
L["Which addons' minimap buttons go in the drawer. The others stay on the minimap's edge. None: every button stays on the edge."] = "어떤 애드온의 미니맵 버튼을 서랍에 넣을지 선택합니다. 나머지 버튼은 미니맵 가장자리에 그대로 표시됩니다. 없음: 모든 버튼을 가장자리에 표시합니다."
L["Which button a sub-radial shows when you open the radial again:\n* Reset on Close: its first button\n* Remember: the one you scrolled to last"] = "방사형 메뉴를 다시 열었을 때 하위 방사형 메뉴에 표시할 버튼:\n* 닫을 때 초기화: 첫 번째 버튼을 표시합니다.\n* 기억: 마지막으로 선택했던 버튼을 표시합니다."
L["Which colours you get:\n* Automatic: Tank in Defensive Stance, Bear Form or Righteous Fury, or with the Tank role in your group\n* Tank or Damage & Healer: always that one"] = "적용할 색상:\n* 자동: 방어 태세, 곰 변신 또는 성스러운 분노 상태이거나 파티에서 방어 담당자 역할일 때 방어 담당자 색상을 사용합니다.\n* 방어 담당자 또는 공격 및 치유 담당자: 선택한 역할의 색상을 항상 사용합니다."
L["Which corner of the HUD Tooltip box the tooltip grows from. Automatic: Blizzard picks the nearest one, so the tooltip can switch sides when you move the box."] = "HUD 툴팁 상자의 어느 모서리를 기준으로 툴팁이 확장될지 선택합니다. 자동: 블리자드가 가장 가까운 모서리를 선택하므로 상자를 이동하면 툴팁이 표시되는 방향이 바뀔 수 있습니다."
L["Which elixirs the reminders look for:\n* Ticked Ones: the ones ticked in Elixirs and More\n* Those in Your Bags: every elixir you carry, nothing to tick"] = "알림에서 확인할 비약:\n* 선택한 비약: 비약 및 기타 항목에서 선택한 비약만 확인합니다.\n* 가방에 있는 비약: 가방에 보유한 모든 비약을 확인합니다. 별도로 선택할 필요가 없습니다."
L["Which enemies get a plate:\n* Players\n* NPCs\n* Minions: their pets, totems and guardians\n* Minor Enemies: such as critters that fight back"] = "어떤 적에게 이름표를 표시할지 선택합니다:\n* 플레이어\n* NPC\n* 하수인: 플레이어의 소환수, 토템 및 수호자\n* 약한 적: 반격하는 동물과 같은 생물"
L["Which friends get a plate:\n* Players\n* NPCs\n* Minions: players' pets, totems and guardians"] = "어떤 아군에게 이름표를 표시할지 선택합니다:\n* 플레이어\n* NPC\n* 하수인: 플레이어의 소환수, 토템 및 수호자"
L["Which messages make a chat tab glow when you're on another tab. The glow takes the colour of the newest message: green for guild, blue for party and so on."] = "다른 채팅 탭을 보고 있을 때 어떤 메시지가 채팅 탭을 빛나게 할지 선택합니다. 광채는 가장 최근 메시지의 색상을 따릅니다. 길드 메시지는 녹색, 파티 메시지는 파란색 등으로 표시됩니다."
L["Which NPCs show a name over their head."] = "머리 위에 이름을 표시할 NPC."
L["Which of a player's names shows in Name Only Mode. Players without a surname show their name."] = "이름만 표시 모드에서 플레이어의 어떤 이름을 표시할지 선택합니다. 성이 없는 플레이어는 이름이 표시됩니다."
L["Which of your characters get this radial. Each picks it up at login."] = "이 방사형 메뉴를 사용할 캐릭터를 선택합니다. 각 캐릭터는 로그인할 때 해당 메뉴를 불러옵니다."
L["Which oil or stone the Weapon Oil / Stone reminder picks first:\n* Melee and Tank: stones\n* Caster: wizard oil\n* Healer: mana oil\n* Automatic: by your group role, then your class"] = "무기 오일 / 숫돌 알림에서 우선적으로 선택할 오일 또는 숫돌:\n* 근접 및 방어 담당자: 숫돌\n* 주문 시전자: 마법사 오일\n* 치유 담당자: 마나 오일\n* 자동: 파티 역할을 기준으로 선택하고, 그다음 직업을 기준으로 선택합니다."
L["Which plates move apart so they don't overlap."] = "서로 겹치지 않도록 분리할 이름표."
L["Which plates the Scale and Opacity below change:\n* No Target: every plate while you have no target\n* Targeted: your target's plate\n* Not Targeted: the other plates while you have a target"] = "아래의 크기 및 투명도 설정을 적용할 이름표:\n* 대상 없음: 대상이 없을 때 모든 이름표에 적용합니다.\n* 대상 지정: 현재 대상의 이름표에 적용합니다.\n* 대상 외: 대상이 있을 때 현재 대상 이외의 이름표에 적용합니다."
L["Which style do you like best?"] = "어떤 스타일이 가장 마음에 드나요?"
L["Which tooltips appear at your mouse and follow it. The rest stay in Blizzard's spot, the HUD Tooltip box you move in Edit Mode."] = "마우스 위치에 나타나 마우스를 따라다닐 툴팁을 선택합니다. 나머지 툴팁은 블리자드의 기본 위치인 편집 모드에서 이동할 수 있는 HUD 툴팁 상자에 표시됩니다."
L["Which way the frames go from the first boss."] = "첫 번째 우두머리를 기준으로 프레임이 배치되는 방향."
L["Which way the frames go from the first member."] = "첫 번째 구성원을 기준으로 프레임이 배치되는 방향."
L["Which way the frames grow from the first member."] = "첫 번째 구성원을 기준으로 프레임이 확장되는 방향."
L["Which way the icons go from the first one."] = "첫 번째 아이콘을 기준으로 아이콘이 배치되는 방향."
L["Which way the raid grows as groups join. Rows grow down or up, columns right or left. The main tank frames follow rows."] = "파티가 추가될 때 공격대 프레임이 확장되는 방향. 행은 위 또는 아래로, 열은 오른쪽 또는 왼쪽으로 확장됩니다. 주 방어 담당자 프레임은 행을 따라 배치됩니다."
L["Which way the second frame goes from the first."] = "첫 번째 프레임을 기준으로 두 번째 프레임이 배치되는 방향."
L["While an effect runs, the ability's own cooldown shows in the icon's corner."] = "효과가 지속되는 동안 해당 능력 자체의 재사용 대기시간이 아이콘 모서리에 표시됩니다."
L["While an icon shows its tooltip, mouseover macros don't reach the frame. Hide in Combat keeps them working in fights."] = "아이콘의 툴팁이 표시되는 동안에는 마우스오버 매크로가 프레임에 적용되지 않습니다. 전투 중 숨기기를 활성화하면 전투 중에도 매크로가 정상적으로 작동합니다."
L["While Heroic Strike, Cleave, Maul or Raptor Strike waits for the next swing, the bar takes its colour (set in Bar Colours)."] = "영웅의 일격, 회전베기, 후려치기 또는 랩터의 일격이 다음 무기 공격을 기다리는 동안 바가 해당 기술의 색상으로 표시됩니다. 색상은 바 색상에서 설정할 수 있습니다."
L["While you fish, music and ambience go down and sound effects go up, so you hear the bobber splash."] = "낚시하는 동안 음악과 환경음의 볼륨을 낮추고 효과음의 볼륨을 높여 낚싯대 찌가 물에 튀는 소리를 잘 들을 수 있게 합니다."
L["While your interrupt is cooling down, a mark shows where on the cast it will be ready."] = "차단 기술의 재사용 대기시간이 진행되는 동안 시전 막대에 해당 기술을 다시 사용할 수 있게 되는 시점이 표시됩니다."
L["Whisper"] = "귓속말"
L["Whisper Markers"] = "귓속말 표시"
L["Whisper Sound"] = "귓속말 소리"
L["Whisper Target"] = "귓속말 대상"
L["Whispers"] = "귓속말"
L["Who the spell is aimed at, right of the bar, in their class colour."] = "주문의 대상이 누구인지 바 오른쪽에 해당 대상의 직업 색상으로 표시합니다."
L["Who your focus is targeting."] = "주시 대상이 지정한 대상."
L["Who your target is targeting."] = "현재 대상이 지정한 대상."
L["Whose buffs it watches."] = "강화 효과를 추적할 대상."
L["Whose names show over players' heads, yours included."] = "자신을 포함하여 플레이어의 머리 위에 이름을 표시할 대상."
L["Wider Vendor Window"] = "더 넓은 상인 창"
L["Width"] = "너비"
L["Winner: %s"] = "승자: %s"
L["With a fishing pole equipped, right-click the world twice quickly to cast Fishing."] = "낚싯대를 착용한 상태에서 월드 화면을 빠르게 두 번 우클릭하면 낚시를 시작합니다."
L["With a sort that puts new icons in the middle, it can play on the last icon instead of the new one."] = "새 아이콘을 가운데에 배치하는 정렬 방식에서는 새 아이콘 대신 마지막 아이콘에 효과가 재생될 수 있습니다."
L["With another nameplate addon on, FlareUI leaves the plates to it"] = "다른 이름표 애드온이 활성화되어 있으면 FlareUI는 이름표 표시를 해당 애드온에 맡깁니다."
L["With the Meter tab in the chat, the meter fades with the chat."] = "채팅에 측정기 탭이 있으면 측정기도 채팅창과 함께 희미해집니다."
L["With Those in Your Bags, one icon shows while you carry none and have none on."] = "가방에 있는 비약을 기준으로 설정하면 비약을 소지하지 않았고 현재 사용 중인 비약도 없을 때 아이콘 하나가 표시됩니다."
L["With your bags full, clicking an item in the loot window first deletes your cheapest grey item to make room."] = "가방이 가득 찬 상태에서 전리품 창의 아이템을 클릭하면 공간을 확보하기 위해 가장 저렴한 회색 아이템을 먼저 삭제합니다."
L["Without an answer, the old scale comes back in 15 seconds."] = "응답하지 않으면 15초 후 이전 크기로 돌아갑니다."
L["Without the Filter button, every tracked quest shows."] = "필터 버튼이 없으면 추적 중인 모든 퀘스트가 표시됩니다."
L["Without Zone Headings, they come after all your tracked quests."] = "지역 제목을 사용하지 않으면 해당 항목은 추적 중인 모든 퀘스트 뒤에 표시됩니다."
L["World"] = "월드"
L["World Markers"] = "월드 징표"
L["World Names"] = "월드 이름"
L["Worn Trinkets"] = "착용 중인 장신구"
L["Wowhead Link"] = "Wowhead 링크"
L["Wowhead link (Ctrl+C to copy)"] = "Wowhead 링크 (Ctrl+C로 복사)"
L["Wowhead shows the ID in the spell's web address."] = "Wowhead에서는 주문의 웹 주소에 ID가 표시됩니다."
L["Wrap"] = "줄 바꿈"
L["WTB %s x20, paying well"] = "구매 희망: %s 20개, 후하게 지불합니다."
L["XP"] = "경험치"
L["XP Bar"] = "경험치 바"
L["XP Bar Colours"] = "경험치 바 색상"
L["XP per hour"] = "시간당 경험치"
L["XP Text"] = "경험치 텍스트"
L["Yell"] = "외치기"
L["Yellow"] = "노란색"
L["You can have two meter windows. Close one to open another."] = "측정기 창은 두 개까지 사용할 수 있습니다. 하나를 닫으면 다른 창을 열 수 있습니다."
L["You can switch any time, and each style keeps its own setup. Party and raid frames come on too: turn them off in /fui if you use others."] = "언제든지 스타일을 전환할 수 있으며 각 스타일은 고유한 설정을 유지합니다. 파티 및 공격대 프레임도 함께 활성화됩니다. 다른 애드온을 사용한다면 /fui에서 해당 프레임을 끄세요."
L["You can't create macros in combat."] = "전투 중에는 매크로를 만들 수 없습니다."
L["You changed colours without applying them."] = "색상을 변경했지만 적용하지 않았습니다."
L["You Hold It"] = "네가 들고 있어"
L["You no take candle!"] = "촛불은 네 것이 아니다!"
L["You: %s"] = "나: %s"
L["Your account macros are full. Delete one and try again."] = "계정 매크로가 가득 찼습니다. 하나를 삭제한 후 다시 시도하세요."
L["Your Auras"] = "내 오라"
L["Your Auras First"] = "내 오라 우선"
L["Your bag slots down the side of the combined backpack:\n* Drag bags in and out\n* Point at one to highlight its items"] = "통합 가방 한쪽에 개별 가방 슬롯을 표시합니다:\n* 가방을 끌어다 놓아 넣거나 뺄 수 있습니다.\n* 가방에 마우스를 올리면 해당 가방의 아이템이 강조 표시됩니다."
L["Your bags and what you loot."] = "가방과 획득한 전리품."
L["Your bags open with the character window and close with it."] = "캐릭터 창을 열면 가방도 함께 열리고, 캐릭터 창을 닫으면 가방도 함께 닫힙니다."
L["Your bar on the Threat tab flashes as you near the point where you pull the enemy."] = "적의 위협을 끌어오기 직전에 위협 수준 탭의 내 바가 깜박입니다."
L["Your Blizzard settings aren't touched."] = "블리자드 설정은 변경되지 않습니다."
L["Your breath, fatigue and feign death timers as bars in FlareUI's style, in place of Blizzard's."] = "블리자드 기본 표시 대신 숨 참기, 피로도 및 죽은 척 타이머를 FlareUI 스타일의 바 형태로 표시합니다."
L["Your buffs and debuffs in FlareUI's style."] = "내 강화 효과와 약화 효과를 FlareUI 스타일로 표시합니다."
L["Your Cast"] = "내 시전"
L["Your Cast Bar"] = "내 시전 바"
L["Your cast bar as its own frame, in FlareUI's style. Off: Blizzard's cast bar."] = "내 시전 바를 FlareUI 스타일의 독립된 프레임으로 표시합니다. 끄면 블리자드 기본 시전 바를 사용합니다."
L["Your Channel"] = "내 정신 집중"
L["Your Characters"] = "내 캐릭터"
L["Your Class"] = "내 직업"
L["Your combo points as a segmented bar."] = "연계 점수를 여러 칸으로 나뉜 바 형태로 표시합니다."
L["Your controller rumbles for:\n* Ready checks\n* Queue invites\n* Summons and resurrections\n* Group invites"] = "다음 상황에서 게임패드가 진동합니다:\n* 전투 준비 확인\n* 대기열 초대\n* 소환 및 부활\n* 파티 초대"
L["Your crafting material bag sits at the bottom of the combined backpack instead of in its own window."] = "제작 재료 가방을 별도의 창 대신 통합 가방 아래쪽에 표시합니다."
L["Your empty slots show as one, after your items, with the number of free slots on it."] = "빈 가방 칸을 아이템 뒤에 하나의 항목으로 모아 표시하고, 남은 칸 수를 함께 보여줍니다."
L["Your focus gets its own colour."] = "주시 대상에 별도의 색상을 적용합니다."
L["Your framerate and latency in the clock's tooltip."] = "시계 툴팁에 프레임률과 지연 시간을 표시합니다."
L["Your friendly UI overhowl"] = "아군 UI 오버울"
L["Your group buffs stay hidden while your group role is one of these. Your own buffs still show."] = "파티 역할이 다음 중 하나일 때 파티 강화 효과를 숨깁니다. 자신의 강화 효과는 계속 표시됩니다."
L["Your guild's members show in Blizzard's guild green."] = "길드원을 블리자드의 길드 전용 녹색으로 표시합니다."
L["Your health as its own bar."] = "내 생명력을 별도의 바 형태로 표시합니다."
L["Your keybinds on the Essential and Utility icons."] = "필수 및 유틸리티 아이콘에 단축키를 표시합니다."
L["Your keys sit at the bottom of the combined backpack instead of in a keyring window."] = "열쇠를 열쇠고리 창 대신 통합 가방 아래쪽에 표시합니다."
L["Your macro list is full. Delete one and try again."] = "매크로 목록이 가득 찼습니다. 하나를 삭제한 후 다시 시도하세요."
L["Your mana while in cat or bear form."] = "표범 변신 또는 곰 변신 상태일 때의 마나를 표시합니다."
L["Your old layout stays: switch back any time from the Layout menu"] = "이전 레이아웃은 그대로 유지됩니다. 레이아웃 메뉴에서 언제든지 다시 전환할 수 있습니다."
L["Your Own"] = "내 것"
L["Your own auras lead the row. Works with Time Left or Name."] = "내 오라를 줄의 맨 앞에 배치합니다. 남은 시간 또는 이름 정렬과 함께 작동합니다."
L["Your own auras lead, the rest follow in the same order."] = "내 오라를 맨 앞에 배치하고 나머지는 같은 순서로 뒤따라 배치합니다."
L["Your own frame first, with the party."] = "파티 프레임과 함께 내 프레임을 맨 앞에 표시합니다."
L["Your own reminder for this class: a spell or buff by name or ID, or an item to use."] = "이 직업에서 사용할 사용자 지정 알림을 추가합니다. 이름이나 ID로 주문 또는 강화 효과를 지정하거나 사용할 아이템을 지정할 수 있습니다."
L["Your own reminders for this class. Untick one to remove it. None removes them all."] = "이 직업에 사용할 사용자 지정 알림입니다. 항목의 선택을 해제하면 해당 알림이 제거됩니다. 없음을 선택하면 모두 제거됩니다."
L["Your paladin seal and its time left, each seal in its own colour."] = "성기사의 문장과 남은 시간을 표시하며, 각 문장은 고유한 색상으로 표시됩니다."
L["Your party frame shows even when you're not in a group, so you can click-cast on yourself."] = "파티에 속해 있지 않아도 파티 프레임을 표시하여 자신에게 클릭 시전을 할 수 있습니다."
L["Your party, in one of two styles:\n* Classic: like the player frame\n* Raid Style: compact tiles"] = "파티를 두 가지 스타일 중 하나로 표시합니다:\n* 클래식: 플레이어 프레임과 같은 스타일\n* 공격대 스타일: 간결한 타일 형태"
L["Your pet's happiness face, and where it sits."] = "소환수의 행복도 표정과 표시 위치."
L["Your player and pet frames stay shown while you're in a party. Off: they hide in a party and come back solo and in a raid. Your frame in the party has the same right-click menu, and your pet's happiness."] = "파티에 속해 있을 때도 플레이어와 소환수 프레임을 계속 표시합니다. 끄면 파티에서는 숨겨지고 혼자 있거나 공격대에 있을 때 다시 표시됩니다. 파티 상태에서도 내 프레임의 마우스 오른쪽 버튼 메뉴와 소환수의 행복도가 동일하게 표시됩니다."
L["Your player and pet frames stay shown while you're in a raid. Off: they hide in a raid and come back solo and in a party."] = "공격대에 속해 있을 때도 플레이어와 소환수 프레임을 계속 표시합니다. 끄면 공격대에서는 숨겨지고 혼자 있거나 파티에 있을 때 다시 표시됩니다."
L["Your player, pet, target and focus frames."] = "플레이어, 소환수, 대상 및 주시 대상 프레임."
L["Your rage, energy, mana or focus."] = "분노, 기력, 마나 또는 집중."
L["Your screen set up the way FlareUI is made to look."] = "FlareUI가 의도한 모습으로 화면을 구성합니다."
L["your summoner"] = "소환한 플레이어"
L["Your Target"] = "내 대상"
L["Your target's bar lights up in the target colour."] = "대상의 바를 대상 색상으로 밝게 표시합니다."
L["Your target's border in the target colour."] = "대상의 테두리를 대상 색상으로 표시합니다."
L["Your target's plate stays at the edge of the screen when the unit moves off it."] = "대상이 화면 밖으로 이동하면 대상의 이름표를 화면 가장자리에 계속 표시합니다."
L["Your threat on an enemy, as a percent, in its tooltip."] = "적에 대한 내 위협 수준을 해당 적의 툴팁에 백분율로 표시합니다."
L["Your threat on this unit as a percent, in threat colours. Above the portrait ring, or after the health value in Modern Style."] = "이 유닛에 대한 내 위협 수준을 위협 수준 색상으로 백분율 표시합니다. 초상화 테두리 위에 표시하거나, 모던 스타일에서는 생명력 수치 뒤에 표시합니다."
L["Your unit frames: you, your target, your party and more."] = "내 유닛 프레임입니다. 플레이어, 대상, 파티 등을 표시합니다."
L["Your volumes return when you move, fight or stop fishing for a while."] = "이동하거나 전투를 시작하거나 일정 시간 낚시를 하지 않으면 볼륨이 원래대로 돌아갑니다."
L["Your worn gear shows beside an item's tooltip only while you hold Shift."] = "Shift 키를 누르고 있을 때만 아이템 툴팁 옆에 현재 착용 중인 장비를 표시합니다."
L["Zone Headings"] = "지역 제목"
L["Zone Levels on the World Map"] = "세계 지도에 지역 레벨 표시"
L["Zone Name"] = "지역 이름"
L["Zone Text"] = "지역 텍스트"
L["Zoom Speed"] = "확대/축소 속도"
L["Zooms the minimap back out a while after you zoom in."] = "미니맵을 확대하면 잠시 후 자동으로 다시 축소합니다."
L["%s changes the chat too, so it can look doubled or broken. Use only one of the two."] = "%s도 채팅을 변경하므로 화면이 중복되거나 깨져 보일 수 있습니다. 두 애드온 중 하나만 사용하세요."
